    	}

    function rememberFreeBlessRewardName(id, name) {
    		name = normalizeFreeBlessRewardName(name, id);
    		if (!Number.isInteger(id) || id <= 0 || !name) return "";
    		const cache = getFreeBlessRewardNameCache();
    		const key = String(id);
    		if (cache[key] === name) return name;
    		if (!(key in cache) && freeBlessRewardNameCacheSize >= FREE_BLESS_REWARD_NAME_CACHE_LIMIT) {
    			const removableKey = Object.keys(cache).find((cachedId) => !(cachedId in FREE_BLESS_REWARD_NAME_SEEDS));
    			if (removableKey) delete cache[removableKey];
    			else return name;
    		} else if (!(key in cache)) freeBlessRewardNameCacheSize += 1;
    		cache[key] = name;
    		freeBlessRewardNameCacheDirty = !0;
    		return name;
    	}

    function flushFreeBlessRewardNameCache() {
