    async function summarizeFreeBlessRewards(rewardList) {
    		let list = [];
    		try {
    			if (Array.isArray(rewardList)) list = rewardList;
    			else if (rewardList && "number" == typeof rewardList.length) list = Array.from(rewardList);
    		} catch (_) {}
    		const rewards = list.map((item) => {
    			const id = Number(item && (item.GoodsBaseID || item.BaseID || item.ItemID || item.itemId || 0));
    			if (!Number.isInteger(id) || id <= 0) return null;
    			const count = Number(item && (item.ChangeCount || item.GoodsNum || item.ItemNum || item.Count || item.count || 0));
    			return { id, count, name: resolveFreeBlessRewardNameImmediately(item, id) };
    		}).filter(Boolean);
    		const unresolved = new Set(rewards.filter((reward) => !reward.name).map((reward) => reward.id));
    		const deadline = Date.now() + FREE_BLESS_REWARD_NAME_WAIT_MS;
    		while (unresolved.size && Date.now() < deadline) {
    			await sleep(Math.min(FREE_BLESS_REWARD_NAME_POLL_MS, Math.max(1, deadline - Date.now())));
    			for (const id of Array.from(unresolved)) {
    				const cachedName = getFreeBlessRewardNameCache()[String(id)] || "";
    				const name = cachedName || readFreeBlessDefinitionName(id);
    				if (!name) continue;
    				const rememberedName = cachedName || rememberFreeBlessRewardName(id, name);
    				for (const reward of rewards) if (reward.id === id && !reward.name) reward.name = rememberedName;
    				unresolved.delete(id);
    			}
    		}
    		flushFreeBlessRewardNameCache();
    		const descriptors = rewards.map(({ id, count, name }) =>
    			`${name ? name + "(" : ""}ID:${id}${name ? ")" : ""}${Number.isFinite(count) && count > 1 ? `x${count}` : ""}`
    		).slice(0, 8);
    		return `奖励${list.length}项${descriptors.length ? `(${descriptors.join(",")})` : ""}`;
    	}

    function waitForFreeBlessReward(gameGoodsManager, rewardEvent, trigger, expectedType) {
        let cancel = () => {};
        const promise = new Promise(resolve => {
            const caller = { __localFreeBlessRewardListener: true };
            let settled = false, timer = null;
            const onReward = (rewardList, rewardType) => {
                if (expectedType != null && String(rewardType) !== String(expectedType)) return;
                finish({ status: 'reward', rewardList, rewardType });
            };
            const finish = result => {
                if (settled) return;
                settled = true;
                if (timer) clearTimeout(timer);
                try { gameGoodsManager.off(rewardEvent, caller, onReward); } catch (_) {}
                resolve(result);
            };
            cancel = () => finish({ status: 'cancelled' });
            try {
                gameGoodsManager.on(rewardEvent, caller, onReward);
                timer = setTimeout(() => finish({ status: 'timeout' }), FREE_BLESS_RESPONSE_TIMEOUT_MS);
                trigger();
            } catch (error) { finish({ status: 'error', error }); }
        });
        promise.cancel = () => cancel();
        return promise;
    }

    function waitForGameEvent(emitter, eventName, trigger, timeoutMs) {
