    				if (!manager && !missing.includes(name)) missing.push(name);
    			};
    			requireManager('freeBless', 'BlessNewManager');
    			if (selection.freeBless) requireManager('freeBless', 'GameGoodsManager');
			requireManager('activityAll', 'ActivityManager');
			requireManager('newJd', 'ActivityManager');
