    const DAILY_STATE_CONFIRM_TIMEOUT_MS = 2600;

    const DAILY_STATE_CONFIRM_POLL_MS = 150;

    const DAILY_PROTOCOL_RESPONSE_TIMEOUT_MS = 2800;

    const DAILY_REWARD_PROTOCOL_IDS = Object.freeze({
    		freeLottery: 22879,
		freeBless: 170140,
		setOut: 200020,
		activityAll: 26102,
		newJd: 170297,
    		activityTasks: 170036,
