    function normalizeGameBoolean(value) {
    		if (value === !1 || value == null || value === 0 || value === "0" || value === "false") return !1;
    		return !!value;
    	}

    function readGameBoolean(owner, name, args) {
    		if (!owner) return { available: !1, value: !1, kind: "owner-missing" };
    		let member;
    		try { member = owner[name]; } catch (error) {
    			return { available: !1, value: !1, kind: "read-error", error };
    		}
    		if (member == null) return { available: !1, value: !1, kind: "missing" };
    		try {
    			const isFunction = "function" == typeof member;
    			const raw = isFunction ? member.apply(owner, Array.isArray(args) ? args : []) : member;
    			return { available: !0, value: normalizeGameBoolean(raw), raw, kind: isFunction ? "function" : "property" };
    		} catch (error) {
    			return { available: !1, value: !1, kind: "call-error", error };
    		}
    	}

    async function waitForGameBoolean(readCurrent, expected) {
    		const deadline = Date.now() + DAILY_STATE_CONFIRM_TIMEOUT_MS;
    		let latest = null;
    		do {
    			try { latest = readCurrent(); } catch (error) { latest = { available: !1, value: !1, kind: "read-error", error }; }
    			if (latest && latest.available && latest.value === expected) return { confirmed: !0, latest };
    			if (Date.now() >= deadline) break;
    			await sleep(DAILY_STATE_CONFIRM_POLL_MS);
    		} while (Date.now() <= deadline);
    		return { confirmed: !1, latest };
    	}

    function describeDailyReadFailure(result, em) {
    		if (!result) return "状态不可读";
    		if (result.error) return em(result.error);
    		return result.kind || "状态不可读";
    	}

    function createDailyProtocolResponseWaiter(manager, protocolId, timeoutMs = DAILY_PROTOCOL_RESPONSE_TIMEOUT_MS, matches = null) {
    		const proxy = resolveMailProtocolProxy(manager);
    		if (!proxy || "function" != typeof proxy.AddEventListener || "function" != typeof proxy.RemoveEventListener) {
    			return {
    				supported: !1,
    				promise: Promise.resolve({ status: "unsupported", protocolId }),
    				cancel: () => {}
    			};
    		}
    		const owner = { __localDailyProtocolListener: protocolId };
    		let active = !1, finish = () => {};
    		const promise = new Promise((resolve) => {
    			let timer = null;
    			const cleanup = () => {
    				if (timer) clearTimeout(timer);
    				if (active) {
    					try { proxy.RemoveEventListener(protocolId, owner, handler); } catch (_) {}
    				}
    				active = !1;
    			};
    			const complete = (value) => {
    				if (!active && value && value.status === "response") return;
    				cleanup();
    				resolve(value);
    			};
    			const accountAtStart = readCurrentGameAccountId();
            const handler = (packet) => {
                if (accountAtStart && readCurrentGameAccountId() !== accountAtStart) return;
                if (matches && !matches(packet)) return;
                complete({ status: "response", protocolId, packet });
            };
    			finish = complete;
    			try {
    				proxy.AddEventListener(protocolId, owner, handler);
    				active = !0;
    				timer = setTimeout(() => complete({ status: "timeout", protocolId }), Math.max(500, Number(timeoutMs) || DAILY_PROTOCOL_RESPONSE_TIMEOUT_MS));
    			} catch (error) {
    				complete({ status: "error", protocolId, error });
    			}
    		});
    		return { supported: !0, promise, cancel: () => finish({ status: "cancelled", protocolId }) };
    	}

    function dailyProtocolScopes(reply) {
    		const packet = reply && reply.packet;
    		const protocol = packet && packet.Protocol ? packet.Protocol : packet;
    		const nested = protocol && protocol.Data && protocol.Data.ProtoObj;
    		return [nested, protocol].filter((item, index, list) => item && "object" == typeof item && list.indexOf(item) === index);
    	}

    function readDailyProtocolResult(reply) {
    		for (const scope of dailyProtocolScopes(reply)) {
    			for (const key of ["result", "Result", "errCode", "ErrCode", "error_id", "errorId"]) {
    				if (!Object.prototype.hasOwnProperty.call(scope, key) || scope[key] == null || scope[key] === "") continue;
    				const numeric = Number(scope[key]);
    				return { present: !0, key, value: Number.isFinite(numeric) ? numeric : scope[key] };
    			}
    		}
    		return { present: !1, key: "", value: null };
    	}

    function summarizeDailyProtocolFields(reply) {
    		const fields = [];
    		const seen = new Set();
    		for (const scope of dailyProtocolScopes(reply)) {
    			for (const key of ["roundId", "count", "termId", "rewardId", "id", "Id", "type", "is_bp", "is_all"]) {
    				if (seen.has(key) || !Object.prototype.hasOwnProperty.call(scope, key)) continue;
    				const value = scope[key];
    				if (["string", "number", "boolean"].includes(typeof value) && String(value).length <= 48) {
    					seen.add(key);
    					fields.push(`${key}=${String(value)}`);
    				}
    			}
    		}
    		return fields.slice(0, 6).join(",");
    	}

    function describeDailyProtocolReply(protocolId, reply) {
    		if (!reply || reply.status === "timeout") return `协议${protocolId}未捕获回包`;
    		if (reply.status === "unsupported") return `协议${protocolId}监听不可用`;
    		if (reply.status === "error") return `协议${protocolId}监听失败`;
    		if (reply.status !== "response") return `协议${protocolId}${reply.status ? ":" + reply.status : ""}`;
    		const result = readDailyProtocolResult(reply);
    		const fields = summarizeDailyProtocolFields(reply);
    		return `协议${protocolId}已回包${result.present ? `,${result.key}=${String(result.value)}` : ""}${fields ? `,${fields}` : ""}`;
    	}

    function recordDailyProtocolResult(label, protocolId, reply, transition, done, requested, skipped, errors, em, extraDetail = "") {
    		const result = readDailyProtocolResult(reply);
    		if (reply && reply.status === "error") {
    			errors.push(`${label}:协议监听失败:${em(reply.error)}`);
    			return;
    		}
    		if (reply && reply.status === "response" && result.present && Number(result.value) !== 0) {
    			skipped.push(`${label}:服务器拒绝(返回码${String(result.value)})`);
    			return;
    		}
    		if ((reply && reply.status === "response" && result.present && Number(result.value) === 0) || (transition && transition.confirmed)) {
    			done.push(`${label}(${reply && reply.status === "response" && result.present ? "服务器确认成功" : "官方状态确认成功"})`);
    			return;
    		}
    		const latest = transition && transition.latest;
    		const stateDetail = latest && !latest.available ? ":状态复核失败-" + describeDailyReadFailure(latest, em) : "";
    		requested.push(`${label}(请求已发送但未确认${stateDetail})`);
    	}

    function addNumericIdsFromGameCollection(value, add, valueFields = []) {
    		if (!value || "function" != typeof add) return;
    		try {
    			const addCandidate = (candidate) => {
    				if (candidate && "object" == typeof candidate) {
    					for (const field of valueFields) {
    						try { if (candidate[field] != null) add(candidate[field]); } catch (_) {}
    					}
    				} else add(candidate);
    			};
    			for (const item of rewardCatalogValues(value)) addCandidate(item);
    			for (const field of ["keys", "_objKeys"]) {
    				let keys = null;
    				try { keys = value[field]; } catch (_) {}
    				if (Array.isArray(keys) || keys && "number" == typeof keys.length) Array.from(keys).forEach(add);
    			}
