    			if ("function" == typeof value.forEach) {
    				const sequence = Array.isArray(value) || "number" == typeof value.length;
    				value.forEach((item, key) => { if (!sequence) add(key); addCandidate(item); });
    			}
    		} catch (_) {}
    	}

    function getFreeBlessRoundIds(manager) {
    		const ids = [];
    		const add = (value) => {
    			const id = Number(value);
    			if (Number.isFinite(id) && id > 0 && !ids.includes(id)) ids.push(id);
    		};
    		try { addNumericIdsFromGameCollection(manager && manager.InfoIds, add, ["RoundId", "roundId", "Id", "ID", "id"]); } catch (_) {}
    		for (const field of ["infoDic", "changeInfoDic", "InfoDic", "InfoDict", "BlessInfoDic", "QifuInfoDic"]) {
    			try { addNumericIdsFromGameCollection(manager && manager[field], add, ["RoundId", "roundId", "Id", "ID", "id"]); } catch (_) {}
    		}
