    	}

    async function loadCurrentFreeBlessRoundIds(manager) {
    		let roundIds = getFreeBlessRoundIds(manager);
    		if (roundIds.length || !manager) return { roundIds, requestedConfig: !1, requestError: "" };
    		let requestedConfig = !1, requestError = "";
    		try {
    			// 新活动的 infoDic/InfoIds 会在 CLIENT_QIFU_NEW_INFO_RESP 回包后才填充。
    			// 自动流程比活动页初始化更早，必须主动走官方列表请求，不能把“尚未回包”误判成无入口。
    			if ("function" == typeof manager.SendAllListReq) {
    				manager.SendAllListReq();
    				requestedConfig = !0;
    			} else if ("function" == typeof manager.SendClientSecretInfoReqs) {
    				manager.SendClientSecretInfoReqs(0);
    				requestedConfig = !0;
    			}
    		} catch (error) {
    			requestError = error && error.message ? error.message : String(error);
    		}
    		if (requestError) return { roundIds, requestedConfig, requestError };
    		// 正常回包通常远小于 1 秒；4 秒只是首轮配置未就绪时的总兜底，不会逐入口等待。
    		for (let attempt = 0; attempt < 40 && !roundIds.length; attempt += 1) {
    			await sleep(100);
    			roundIds = getFreeBlessRoundIds(manager);
    		}
    		return { roundIds, requestedConfig, requestError };
    	}

    function getSetOutTermIds(manager) {
    		const ids = [];
    		const add = (value) => {
    			const id = Number(value);
    			if (Number.isFinite(id) && id > 0 && !ids.includes(id)) ids.push(id);
    		};
    		try {
    			const dictionary = manager && manager.PassdataDic;
    			addNumericIdsFromGameCollection(dictionary, add, ["TermId", "termId", "Type", "type", "Id", "ID", "id"]);
    		} catch (_) {}
    		// 兼容旧客户端尚未暴露字典 keys 的情况，但只保留确实已有数据的旧编号。
    		for (const legacyId of [1, 2, 3]) {
    			try { if (manager.GetPassData(legacyId)) add(legacyId); } catch (_) {}
    		}
    		return ids;
    	}

    const OFFICER_CONFIG_SCAN_LIMIT = 38;

    const OFFICER_VERIFIED_SYSTEM_MAX_LEVEL = 38;

    function configuredOfficerTargetLevel(manager, requestedLevel) {
    		// maxOfficerLv / MaxOfficerLv 是“账号目前已达到的最高官阶”，不是配置允许的上限。
    		// 全服统一上限固定为 LV38，用户输入只决定本轮目标等级。
    		const configured = Number(requestedLevel) > 0 ? Number(requestedLevel) : 18;
