    		// 限时武将同样可升阶；只排除已经到期的记录。
    		try {
    			const goodsId = Number(general.GoodsID ?? general.goodsID ?? general.goodsId) || 0;
    			const endTime = Number(general.EndTime ?? general.endTime ?? general.ExpireTime ?? general.expireTime) || 0;
    			if (endTime > 0) {
    				const expiresAtMs = endTime < 1e12 ? endTime * 1000 : endTime;
    				return expiresAtMs > Date.now();
    			}
    			return !hasExplicitForeverFlag && goodsId > 0;
    		} catch (_) { return !1; }
    	}

    function collectUniqueOwnedGenerals(manager) {
    		const unique = new Map();
    		const sources = [], seenNames = new Set(), seenObjects = new Set();
    		const appendSource = (name, source) => {
    			if (!source || "object" != typeof source || seenNames.has(name) || seenObjects.has(source)) return;
    			seenNames.add(name);
    			seenObjects.add(source);
    			sources.push({ name, source });
    		};
    		for (const name of ["SelfGeneralDict", "selfGeneralDict", "SelfGeneralList", "selfGeneralList", "OwnGeneralList", "ownGeneralList"]) {
    			try { appendSource(name, manager && manager[name]); } catch (_) {}
    		}
    		try {
    			for (const name of Object.keys(manager || {})) {
    				if (!/(?:self|own).*general|general.*(?:self|own)/i.test(name)) continue;
    				try { appendSource(name, manager[name]); } catch (_) {}
    			}
    		} catch (_) {}
    		const ownershipVerifierAvailable = sources.length > 0;
    		const sourceCounts = [];
    		let rawCount = 0, rejectedCount = 0;
    		for (const { name, source } of sources) {
    			const entries = ownedGeneralSourceEntries(source);
    			let acceptedCount = 0, invalidIdCount = 0, notOwnedCount = 0, unreadableStarCount = 0;
    			rawCount += entries.length;
    			for (const [rawId, general] of entries) {
    				let id = Number(rawId) || 0;
    				try { id = Number(general && (general.ID ?? general.Id ?? general.id ?? general.GeneralID ?? general.generalId)) || id; } catch (_) {}
    				if (!Number.isInteger(id) || id <= 0) { invalidIdCount += 1; continue; }
    				const ownedGeneral = general;
    				if (!ownershipVerifierAvailable || !isOwnedGeneralRecord(ownedGeneral)) { notOwnedCount += 1; continue; }
    				const state = readOwnedGeneralState(manager, id, ownedGeneral);
    				if (state.star < GENERAL_UPGRADE_MIN_STAR || state.star > GENERAL_UPGRADE_MAX_STAR) { unreadableStarCount += 1; continue; }
    				acceptedCount += 1;
    				if (!unique.has(id)) unique.set(id, state);
    			}
    			const sourceRejectedCount = invalidIdCount + notOwnedCount + unreadableStarCount;
    			rejectedCount += sourceRejectedCount;
    			sourceCounts.push({ name, count: acceptedCount, rawCount: entries.length, rejectedCount: sourceRejectedCount,
    				rejectionBreakdown: { invalidIdCount, notOwnedCount, unreadableStarCount } });
    		}
    		return {
    			generals: Array.from(unique.values()).sort((left, right) => left.id - right.id),
    			sourceCounts: sourceCounts.filter((item) => item.rawCount > 0),
    			ownershipVerifierAvailable,
    			rawCount,
    			acceptedCount: unique.size,
    			rejectedCount
    		};
    	}

    async function scanOwnedGeneralRoster(manager) {
    		const startedAt = Date.now();
    		if (!manager) return { ready: !1, status: "manager-unavailable", stable: !1, ids: [], count: 0, waitedMs: 0, sourceCounts: [] };
    		const deadline = startedAt + GENERAL_UPGRADE_SCAN_TIMEOUT_MS;
    		let previousFingerprint = "", stablePolls = 0, snapshot = { generals: [], sourceCounts: [], ownershipVerifierAvailable: !1 };
    		do {
    			snapshot = collectUniqueOwnedGenerals(manager);
    			const fingerprint = [snapshot.rawCount, snapshot.acceptedCount,
    				snapshot.sourceCounts.map((item) => `${item.name}:${item.rawCount}:${item.count}:${item.rejectedCount}`).join(","),
    				snapshot.generals.map((item) => `${item.id}:${item.star}`).join("|")].join("#");
    			if (snapshot.generals.length && fingerprint === previousFingerprint) stablePolls += 1;
    			else {
    				previousFingerprint = fingerprint;
    				stablePolls = snapshot.generals.length ? 1 : 0;
    			}
    			if (stablePolls >= GENERAL_UPGRADE_SCAN_STABLE_POLLS || Date.now() >= deadline) break;
    			await sleep(GENERAL_UPGRADE_SCAN_POLL_MS);
    		} while (Date.now() <= deadline);
    		const ids = normalizeGeneralUpgradeRosterIds(snapshot.generals.map((item) => item.id));
    		const stable = stablePolls >= GENERAL_UPGRADE_SCAN_STABLE_POLLS;
    		return {
    			ready: snapshot.ownershipVerifierAvailable && stable && ids.length > 0,
    			status: !snapshot.ownershipVerifierAvailable ? "ownership-verifier-unavailable" : !ids.length ? "roster-empty" : stable ? "ready" : "roster-unstable",
    			stable,
    			scanMode: "getOwnGeneral-v2",
    			accountId: readCurrentGameAccountId(),
    			ids,
    			count: ids.length,
    			rawCount: Math.max(0, Number(snapshot.rawCount) || 0),
    			acceptedCount: Math.max(0, Number(snapshot.acceptedCount) || 0),
    			rejectedCount: Math.max(0, Number(snapshot.rejectedCount) || 0),
    			firstId: ids[0] || 0,
    			lastId: ids[ids.length - 1] || 0,
    			waitedMs: Date.now() - startedAt,
    			sourceCounts: snapshot.sourceCounts
    		};
    	}

    async function scanOwnedGeneralRosterInGame() {
    		try {
    			if ("undefined" == typeof laya || "function" != typeof laya.class) return { ready: !1, status: "runtime-unavailable", ids: [], count: 0 };
    			return await scanOwnedGeneralRoster(laya.class("GameGeneralManager"));
    		} catch (error) {
    			return { ready: !1, status: "scan-error", ids: [], count: 0, error: error && error.message ? error.message : String(error) };
    		}
    	}

    async function inspectGeneralUpgradePreflight(manager, accountId, rawCheckedIds, rawRosterCount) {
    		const normalizedAccountId = String(accountId || "").trim();
    		if (!normalizedAccountId) {
    			return {
    				ready: !1,
    				status: "account-not-ready",
    				accountReady: !1,
    				stable: !1,
    				rosterCount: 0,
    				sentinelId: 0,
    				sentinelStar: 0,
    				waitedMs: 0
    			};
    		}
    		const rosterIds = normalizeGeneralUpgradeRosterIds(rawCheckedIds);
    		if (!rosterIds.length) {
    			return {
    				ready: !1,
    				status: "roster-not-scanned",
    				accountReady: !0,
    				stable: !1,
    				rosterCount: 0,
    				sentinelId: 0,
    				sentinelStar: 0,
    				waitedMs: 0
    			};
    		}
    		const startedAt = Date.now();
    		const deadline = startedAt + GENERAL_UPGRADE_PREFLIGHT_TIMEOUT_MS;
    		const sentinelId = rosterIds[0];
    		let previousFingerprint = "", stablePolls = 0, states = [];
    		do {
    			states = rosterIds.map((id) => readOwnedGeneralState(manager, id));
    			const fingerprint = states.map((state) => `${state.id}:${state.star}`).join("|");
    			const allReadable = states.length === rosterIds.length && states.every((state) =>
    				state.star >= GENERAL_UPGRADE_MIN_STAR && state.star <= GENERAL_UPGRADE_MAX_STAR);
    			if (allReadable && fingerprint === previousFingerprint) stablePolls += 1;
    			else {
    				previousFingerprint = fingerprint;
    				stablePolls = allReadable ? 1 : 0;
    			}
    			if (stablePolls >= GENERAL_UPGRADE_PREFLIGHT_STABLE_POLLS) break;
    			if (Date.now() >= deadline) break;
    			await sleep(GENERAL_UPGRADE_PREFLIGHT_POLL_MS);
    		} while (Date.now() <= deadline);
    		const stable = stablePolls >= GENERAL_UPGRADE_PREFLIGHT_STABLE_POLLS;
    		const byId = new Map(states.map((state) => [state.id, state]));
    		const sentinelStar = stable ? Number(byId.get(sentinelId) && byId.get(sentinelId).star) || 0 : 0;
    		return {
    			ready: stable,
    			status: stable ? "ready" : "roster-sentinel-unavailable",
    			accountReady: !0,
    			stable,
    			rosterCount: Math.max(rosterIds.length, Math.floor(Number(rawRosterCount) || 0)),
    			checkedCount: rosterIds.length,
    			sentinelId,
    			sentinelStar,
    			waitedMs: Date.now() - startedAt
    		};
    	}

    function createGeneralUpgradeResponseMonitor(manager) {
    		const watchesById = new Map();
    		const hadOwnEvent = !!manager && Object.prototype.hasOwnProperty.call(manager, "event");
    		const ownEventDescriptor = hadOwnEvent ? Object.getOwnPropertyDescriptor(manager, "event") : null;
    		const originalEvent = manager && "function" == typeof manager.event ? manager.event : null;
    		let wrappedEvent = null, observedSuccessCount = 0;
    		const observeEventPayload = (payload, extraArgs = []) => {
    			const values = Array.isArray(payload)
    				? payload
    				: payload && typeof payload === "object"
    					? [payload.id ?? payload.ID, payload.oldLevel ?? payload.OldLevel, payload.oldExp ?? payload.OldExp,
    						payload.newLevel ?? payload.NewLevel ?? payload.level ?? payload.Level, payload.newExp ?? payload.NewExp ?? payload.exp ?? payload.Exp]
    					: extraArgs;
    			if (!Array.isArray(values) || values.length < 5) return;
    			const id = Math.floor(Number(values[0]) || 0);
    			const oldLevel = Math.floor(Number(values[1]) || 0);
    			const oldExp = Math.max(0, Number(values[2]) || 0);
    			const newLevel = Math.floor(Number(values[3]) || 0);
    			const newExp = Math.max(0, Number(values[4]) || 0);
    			const watch = watchesById.get(id);
    			if (!watch || newLevel + 1 < watch.expectedStar) return;
    			observedSuccessCount += 1;
    			const liveState = readOwnedGeneralState(manager, id);
    			const state = {
    				...liveState,
    				id,
    				star: Math.max(newLevel + 1, Number(liveState.star) || 0),
    				exp: newExp,
    				previousStar: oldLevel + 1,
    				previousExp: oldExp,
    				stateRefreshConfirmed: !0,
    				serverEventConfirmed: !0
    			};
    			rememberGeneralUpgradeState(manager, state);
    			let continuation = null;
    			if ("function" == typeof watch.onConfirmed) {
    				try { continuation = watch.onConfirmed(state); }
    				catch (error) { continuation = { status: "error", error }; }
    			}
    			watch.result = { confirmed: !0, state, continuation, source: "server-event" };
    			watchesById.delete(id);
    		};
    		if (originalEvent) {
    			wrappedEvent = function(type, payload) {
    				const firstPayload = Array.isArray(type) || type && typeof type === "object" ? type : payload;
    				const extraArgs = Array.isArray(type) || type && typeof type === "object"
    					? Array.prototype.slice.call(arguments)
    					: Array.prototype.slice.call(arguments, 1);
    				observeEventPayload(firstPayload, extraArgs);
    				return originalEvent.apply(this, arguments);
    			};
    			try { manager.event = wrappedEvent; } catch (_) { wrappedEvent = null; }
    		}
    		return {
    			watch(id, expectedStar, onConfirmed) {
    				const token = {
    					id: Math.floor(Number(id) || 0),
    					expectedStar: Math.floor(Number(expectedStar) || 0),
    					onConfirmed,
    					result: null
    				};
    				if (token.id > 0) watchesById.set(token.id, token);
    				return token;
    			},
    			cancel(token) {
    				if (token && watchesById.get(token.id) === token) watchesById.delete(token.id);
    			},
    			close() {
    				watchesById.clear();
    				if (wrappedEvent && manager && manager.event === wrappedEvent) {
    					try {
    						if (hadOwnEvent && ownEventDescriptor) Object.defineProperty(manager, "event", ownEventDescriptor);
    						else delete manager.event;
    					} catch (_) {}
    				}
    			},
    			stats() {
    				return { installed: !!wrappedEvent, observedSuccessCount };
    			}
    		};
    	}

    async function waitForGeneralUpgradeTransition(manager, baseline, expectedStar, runDeadlineAt, responseWatch = null, onConfirmed = null) {
    		const startedAt = Date.now();
    		const deadline = Math.min(
    			Math.max(startedAt, Number(runDeadlineAt) || 0),
    			startedAt + GENERAL_UPGRADE_SINGLE_CONFIRM_TIMEOUT_MS
    		);
    		let reads = 0, lastState = readOwnedGeneralState(manager, baseline.id);
    		do {
    			if (responseWatch && responseWatch.result && responseWatch.result.confirmed) {
    				return {
    					...responseWatch.result,
    					reads,
    					waitedMs: Math.max(0, Date.now() - startedAt)
    				};
    			}
    			lastState = readOwnedGeneralState(manager, baseline.id);
    			reads += 1;
    			// 发包前已精确确认起点；发包后只要即时捕获一次目标或更高星级，就足以证明本次变化。
    			if (baseline.star === expectedStar - 1 && lastState.star >= expectedStar) {
    				let continuation = null;
    				if ("function" == typeof onConfirmed) {
    					try { continuation = onConfirmed(lastState); }
    					catch (error) { continuation = { status: "error", error }; }
    				}
    				const confirmedState = { ...lastState, previousStar: baseline.star, stateRefreshConfirmed: !0 };
    				rememberGeneralUpgradeState(manager, confirmedState);
    				return {
    					confirmed: !0,
    					state: confirmedState,
    					continuation,
    					reads,
    					waitedMs: Math.max(0, Date.now() - startedAt)
    				};
    			}
    			if (Date.now() >= deadline) break;
    			await sleep(GENERAL_UPGRADE_CONFIRM_POLL_MS);
    		} while (Date.now() <= deadline);
    		return { confirmed: !1, state: lastState, reads, waitedMs: Math.max(0, Date.now() - startedAt) };
    	}

    function createGeneralUpgradeSendScheduler(runDeadlineAt) {
    		const deadlineAt = Math.max(Date.now(), Number(runDeadlineAt) || 0);
    		const continuationQueue = [], initialQueue = [];
    		let pumping = !1, closed = !1, lastSendAt = 0, firstSendAt = 0, sentCount = 0, urgentContinuationCount = 0;
    		let minimumGapMs = Number.POSITIVE_INFINITY;
    		const recordSent = (urgent = !1) => {
    			const sentAt = Date.now();
    			if (lastSendAt) minimumGapMs = Math.min(minimumGapMs, sentAt - lastSendAt);
    			else firstSendAt = sentAt;
    			lastSendAt = sentAt;
    			sentCount += 1;
    			if (urgent) urgentContinuationCount += 1;
    		};
    		const dequeue = () => continuationQueue.shift() || initialQueue.shift() || null;
    		const expirePending = () => {
    			let entry;
    			while ((entry = dequeue())) entry.resolve({ status: "deadline" });
    		};
    		const pump = async () => {
    			if (pumping) return;
    			pumping = !0;
    			try {
    				while (!closed && (continuationQueue.length || initialQueue.length)) {
    					while (lastSendAt && Date.now() - lastSendAt < GENERAL_UPGRADE_SEND_INTERVAL_MS) {
    						const remainingBudgetMs = deadlineAt - Date.now();
    						if (remainingBudgetMs <= 0) break;
    						await sleep(Math.min(
    							GENERAL_UPGRADE_SEND_INTERVAL_MS - (Date.now() - lastSendAt),
    							remainingBudgetMs
    						));
    					}
    					if (Date.now() >= deadlineAt) {
    						expirePending();
    						break;
    					}
    					// 等待限速间隔期间可能刚加入续阶任务，所以在真正执行前才按优先级取队首。
    					const entry = dequeue();
    					if (!entry) break;
    					let result;
    					try {
    						result = entry.execute();
    					} catch (error) {
    						result = { status: "error", error };
    					}
    					if (result && result.status === "sent") {
    						recordSent(!1);
    					}
    					entry.resolve(result || { status: "skipped" });
    				}
    			} finally {
    				pumping = !1;
    				if (!closed && (continuationQueue.length || initialQueue.length)) void pump();
    			}
    		};
    		return {
    				enqueue(execute, continuation = !1) {
    				if (closed || Date.now() >= deadlineAt) return Promise.resolve({ status: "deadline" });
    				return new Promise((resolve) => {
    					(continuation ? continuationQueue : initialQueue).push({ execute, resolve });
    					void pump();
    				});
    			},
    			dispatchContinuationNow(execute) {
    				if (closed || Date.now() >= deadlineAt) return { status: "deadline" };
    				let result;
    				try { result = execute(); }
    				catch (error) { result = { status: "error", error }; }
    				if (result && result.status === "sent") recordSent(!0);
    				return result || { status: "skipped" };
    			},
    			close() {
    				closed = !0;
    				expirePending();
    			},
    			stats() {
    				return {
    					sentCount,
    					firstSendAt,
    					lastSendAt,
    					urgentContinuationCount,
    					minimumGapMs: Number.isFinite(minimumGapMs) ? minimumGapMs : 0
    				};
    			}
    		};
    	}

    function summarizeGeneralUpgradeRun(counts, selectedCount, reports, reason = "", preflight = null) {
    		const byStage = new Map((reports || []).map((report) => [report.stage, report]));
    		const requestedStages = GENERAL_UPGRADE_STAGES.filter((item) => counts[item.key] > 0);
    		const stages = [];
    		for (const stage of requestedStages) {
    			const report = byStage.get(stage.key);
    			if (!report) continue;
    			const confirmedCount = Array.isArray(report.satisfiedIds)
    				? report.satisfiedIds.length
    				: Array.isArray(report.confirmedIds) ? report.confirmedIds.length : 0;
    			stages.push({
    					key: stage.key,
    					from: stage.from,
    					to: stage.to,
    					targetCount: counts[stage.key],
    					candidateCount: Math.max(0, Number(report.candidateCount) || 0),
    					sentCount: Array.isArray(report.sentIds) ? report.sentIds.length : 0,
    					confirmedCount,
    					alreadySatisfiedCount: Array.isArray(report.alreadySatisfiedIds) ? report.alreadySatisfiedIds.length : 0,
    					transitionConfirmedCount: Array.isArray(report.confirmedIds) ? report.confirmedIds.length : 0,
    					confirmedIds: Array.isArray(report.confirmedIds) ? report.confirmedIds.slice(0, 20) : [],
    					blockedCount: Array.isArray(report.blockedIds) ? report.blockedIds.length : 0,
    					missingCount: Math.max(0, Number(report.missingCount) || 0),
    					unsentCount: Array.isArray(report.unsentIds) ? report.unsentIds.length : 0,
    					unconfirmedCount: Array.isArray(report.unconfirmedIds) ? report.unconfirmedIds.length : 0,
    					materialPlanCount: Array.isArray(report.materialPlans) ? report.materialPlans.length : 0,
    					materialFallbackCount: Array.isArray(report.materialPlans) ? report.materialPlans.filter((item) => item && item.fallback === !0).length : 0,
    					materialUnavailableCount: Array.isArray(report.materialUnavailableIds) ? report.materialUnavailableIds.length : 0,
    					materialPlans: Array.isArray(report.materialPlans) ? report.materialPlans.slice(0, 20) : [],
    					blockedReason: String(report.blockedReason || '')
    				});
    		}
    		const confirmedTotal = stages.reduce((sum, stage) => sum + stage.confirmedCount, 0);
    		const sentTotal = stages.reduce((sum, stage) => sum + stage.sentCount, 0);
    		const targetTotal = requestedStages.reduce((sum, stage) => sum + counts[stage.key], 0);
    		const success = targetTotal === 0 || (stages.length === requestedStages.length
    			&& stages.every((stage) => stage.confirmedCount >= stage.targetCount));
    		const status = targetTotal === 0 ? "no-target" : success ? "success" : confirmedTotal > 0 ? "partial" : sentTotal > 0 ? "unconfirmed" : "failed";
    		const confirmedTransitions = (reports || []).flatMap((report) => (Array.isArray(report.confirmedStates) ? report.confirmedStates : [])
    			.map((state) => ({ id: Math.max(0, Number(state.id) || 0), star: Math.max(0, Number(state.star) || 0) }))
    			.filter((state) => state.id > 0 && state.star >= GENERAL_UPGRADE_MIN_STAR && state.star <= GENERAL_UPGRADE_MAX_STAR));
    		return {
    			enabled: !0,
    			status,
    			success,
    			reason: String(reason || ""),
    			selectedCount: Math.max(0, Number(selectedCount) || 0),
    			targetTotal,
    			sentTotal,
    			confirmedTotal,
    			freshStateGuard: "live-snapshot+stable-target-prefix+known-star-high-water+single-scheduler+15ms-paced+event-first-transition+late-state-reconcile+dynamic-budget",
    			preflight: preflight && "object" == typeof preflight ? { ...preflight } : null,
    			confirmedTransitions,
    			stages
    		};
    	}

    async function batchUpgradeGenerals(manager, rawCounts, context, done, requested, skipped, errors, em) {
    		const batchStartedAt = Date.now();
    		const apiDiagnostic = inspectGeneralUpgradeApiSources(manager);
    		const counts = normalizeGeneralUpgradeCounts(rawCounts);
    		const requestedFirstStage = counts.stage1;
    		if (!requestedFirstStage) {
    			skipped.push("武将升阶:目标人数均为0");
    			return summarizeGeneralUpgradeRun(counts, 0, [], "target-empty");
    		}
    		if (!manager || "function" != typeof manager.sendStarExpAddReq) {
    			skipped.push("武将升阶:接口无");
    			return summarizeGeneralUpgradeRun(counts, 0, [], "interface-unavailable");
    		}
    		const expectedAccountId = String(context && context.accountId || "").trim();
    		if (expectedAccountId) resetGeneralUpgradeKnownStates(expectedAccountId);
    		const liveSnapshot = await scanOwnedGeneralRoster(manager);
    		const snapshotAccountId = String(liveSnapshot && liveSnapshot.accountId || "").trim();
    		const accountMismatch = expectedAccountId && snapshotAccountId && expectedAccountId !== snapshotAccountId;
    		const snapshotReady = !!(liveSnapshot && liveSnapshot.ready && snapshotAccountId && !accountMismatch);
    		if (!snapshotReady) {
    			const status = accountMismatch ? "account-mismatch" : String(liveSnapshot && liveSnapshot.status || "roster-not-scanned");
    			const reason = status === "account-mismatch" ? `实时账号不一致(${snapshotAccountId || "未知"}/${expectedAccountId})`
    				: status === "roster-empty" ? "当前本地没有读到拥有武将"
    				: status === "roster-unstable" ? "拥有武将列表仍在加载变化"
    				: "实时拥有武将快照未就绪";
    			skipped.push(`武将升阶:预检停止(${reason})`);
    			return summarizeGeneralUpgradeRun(counts, 0, [], status, {
    				...(liveSnapshot || {}),
    				ready: !1,
    				status,
    				snapshot: liveSnapshot ? {
    					rawCount: liveSnapshot.rawCount,
    					acceptedCount: liveSnapshot.acceptedCount,
    					rejectedCount: liveSnapshot.rejectedCount,
    					sourceCounts: liveSnapshot.sourceCounts
    				} : null
    			});
    		}
    		resetGeneralUpgradeKnownStates(snapshotAccountId);
    		const rosterIds = normalizeGeneralUpgradeRosterIds(liveSnapshot.ids);
    		const checkedIds = rosterIds.slice(0, Math.max(1, requestedFirstStage));
    		const preflight = await inspectGeneralUpgradePreflight(manager, snapshotAccountId, checkedIds, rosterIds.length);
    		preflight.snapshot = {
    			rawCount: Math.max(0, Number(liveSnapshot.rawCount) || 0),
    			acceptedCount: Math.max(0, Number(liveSnapshot.acceptedCount) || rosterIds.length),
    			rejectedCount: Math.max(0, Number(liveSnapshot.rejectedCount) || 0),
