    function captureOfficerSprintRewardVos(manager) {
    		if (!manager || "function" != typeof manager.GetOfficerRunCommonRewardState ||
    			"function" != typeof manager.OnCheckOfficerRunCommonRewardRed) return [];
    		const name = "GetOfficerRunCommonRewardState";
    		const hadOwn = Object.prototype.hasOwnProperty.call(manager, name);
    		const ownDescriptor = hadOwn ? Object.getOwnPropertyDescriptor(manager, name) : null;
    		const original = manager[name], captured = [];
    		try {
    			manager[name] = function (vo) {
    				if (vo && Number(vo.Id) > 0) captured.push(vo);
    				return original.call(this, vo);
    			};
    			manager.OnCheckOfficerRunCommonRewardRed();
    		} catch (_) {
    		} finally {
    			try {
    				if (hadOwn && ownDescriptor) Object.defineProperty(manager, name, ownDescriptor);
    				else delete manager[name];
    			} catch (_) { try { manager[name] = original; } catch (_) {} }
    		}
    		const seen = new Set();
    		return captured.filter((vo) => {
    			const key = `${Number(vo.Stage) || 0}:${Number(vo.Id) || 0}`;
    			if (seen.has(key)) return !1;
    			seen.add(key);
    			return !0;
    		});
    	}

    const OFFICER_SPRINT_REFRESH_TIMEOUT_MS = 3200;

