    		return rewardVos.map((vo) => {
    			let state = -1;
    			try { state = Number(manager.GetOfficerRunCommonRewardState(vo)); } catch (_) {}
    			return `${Number(vo.Stage) || 0}:${Number(vo.Id) || 0}:${Number.isFinite(state) ? state : -1}`;
    		}).sort().join("|");
    	}

    async function refreshOfficerSprintData(manager) {
    		// 登录早期可能已留下非空旧对象；必须以请求后的对象或奖励状态变化作为刷新信号。
    		const beforeData = manager.curOfficerRunCommonData || null;
