    		const startedAt = Date.now();
    		const protocolWaiter = createDailyProtocolResponseWaiter(
    			manager,
    			DAILY_REWARD_PROTOCOL_IDS.officerSprintData,
    			OFFICER_SPRINT_REFRESH_TIMEOUT_MS
    		);
    		let protocolReply = null, resultCode = null, actId = null;
    		try {
    			manager.SendOfficerRunCommonUserDataReq(0);
    		} catch (error) {
    			protocolWaiter.cancel();
    			throw error;
    		}
    		if (protocolWaiter.supported) {
    			protocolReply = await protocolWaiter.promise;
    			const result = readDailyProtocolResult(protocolReply);
    			if (result.present) resultCode = result.value;
    			for (const scope of dailyProtocolScopes(protocolReply)) {
    				if (!Object.prototype.hasOwnProperty.call(scope, "actId")) continue;
    				const value = Number(scope.actId);
    				actId = Number.isFinite(value) ? value : scope.actId;
    				break;
    			}
    			if (protocolReply.status === "response" && result.present && Number(result.value) !== 0) {
    				return {
    					ready: !1,
    					rejected: !0,
    					resultCode,
    					actId,
    					waitedMs: Math.max(0, Date.now() - startedAt),
    					fingerprint: beforeFingerprint,
    					protocolReply
    				};
    			}
    		}
    		const deadline = startedAt + OFFICER_SPRINT_REFRESH_TIMEOUT_MS;
    		let currentData = manager.curOfficerRunCommonData || null;
    		let currentFingerprint = beforeFingerprint;
    		do {
    			await sleep(OFFICER_SPRINT_REFRESH_POLL_MS);
    			currentData = manager.curOfficerRunCommonData || null;
    			currentFingerprint = officerSprintRewardFingerprint(manager);
