			crossRecords = Array.isArray(durableAccount.crossRecords)
				? durableAccount.crossRecords.filter(record => record && String(record.importedIntoAccountId) === accountId && String(record.originAccountId) !== accountId)
				: [];
			crossAttemptLedger = durableAccount.crossAttemptLedger &&
				typeof durableAccount.crossAttemptLedger === "object" &&
				!Array.isArray(durableAccount.crossAttemptLedger)
				? durableAccount.crossAttemptLedger
				: {};
			if (Array.isArray(durableAccount.userExcludedMids)) {
				userExcludedMids = new Set(durableAccount.userExcludedMids.map(normalizeArchiveMid).filter(Boolean).slice(0, 500));
			}
			lastDurableSaveAt = Number(durableAccount.savedAt) || 0;
		}
		records = records.filter(record => record && !isArchiveMidSuppressed(accountId, record.mid));
		applyOneTimeDurableCompactMigration(accountId);
		for (const record of records) {
			if (!Array.isArray(record.claimAttempts)) record.claimAttempts = [];
			record.lastConfirmedSuccessAttempt = latestExplicitSuccessAttempt(record);
			record.presentInLiveList = false;
		}
		for (const record of crossRecords) {
			if (!Array.isArray(record.claimAttempts)) record.claimAttempts = [];
			const ledgerAttempt = crossAttemptLedger[crossRecordKey(record.originAccountId, record.mid)];
			if (!record.claimAttempts.length && ledgerAttempt) {
				record.claimAttempts = [cloneJson(ledgerAttempt, ledgerAttempt)];
				record.lastClaimResult = record.claimAttempts[0].state || "attempt-recorded";
			}
		}
		rebuildRecordIndex();
		rebuildCrossRecordIndex();
		archiveCount = records.length;
		// 首次升级时把已有 localStorage 归档迁移进微端专用文件；以后则以专用文件为准并同步页面缓存。
		persistAll();
	}

	function persist() {
		const localSaved = persistLocalRecords();
		const durableSaved = persistDurableStore();
		return localSaved && durableSaved;
	}

	function persistCross() {
		const localSaved = persistLocalCross();
		const durableSaved = persistDurableStore();
		return localSaved && durableSaved;
	}

	function persistAll() {
		const recordsSaved = persistLocalRecords();
		const crossSaved = persistLocalCross();
		const durableSaved = persistDurableStore();
		return recordsSaved && crossSaved && durableSaved;
	}

	function asArray(value) {
		if (Array.isArray(value)) return value.slice();
		if (value == null) return [];
		return [value];
	}

	function readAttachmentField(attachment, key) {
		if (!attachment) return [];
		try {
			if (typeof attachment.getStringKey === "function") return asArray(attachment.getStringKey(key));
			if (typeof attachment.get === "function") return asArray(attachment.get(key));
			return asArray(attachment[key]);
		} catch (error) {
			return [];
		}
	}

	function getAttachmentType(mail) {
		const direct = Number(mail && mail.AttachmentType);
		if (Number.isFinite(direct) && direct > 0) return direct;
		const values = readAttachmentField(mail && mail.attachment, "type");
		return Number(values[0]) || 0;
	}

	function mailHasAttachment(mail) {
		if (!mail) return false;
		if (mail.hasAttachMent || mail.hasAttachment || mail.HasAttachment) return true;
		if (getAttachmentType(mail) > 0) return true;
		return ["id", "key"].some(field => readAttachmentField(mail.attachment, field).some(value => value != null && String(value) !== ""));
	}

	function getClaimRoute(attachmentType) {
		if (attachmentType === GIFT_ATTACHMENT) return "single-gift";
		if (attachmentType === ITEM_ATTACHMENT) return "dbs-item";
		return "unsupported";
	}

	function autoWhitelistLiveRecord(record, mail, now) {
		if (!record || !mail || record.presentInLiveList !== true) return false;
		if (!mailHasAttachment(mail)) return false;
		if (!["single-gift", "dbs-item"].includes(record.claimRoute)) return false;
		if (record.jsonAutoClaim === true) return false;
		record.jsonAutoClaim = true;
		record.hasAttachment = true;
		record.autoWhitelistSource = "live-scan";
		record.autoWhitelistedAt = Number(record.autoWhitelistedAt) || Number(now) || Date.now();
		return true;
	}

	function sanitizeImportedArray(value) {
		return asArray(value).slice(0, 100).map(item => {
			if (item == null || ["string", "number", "boolean"].includes(typeof item)) return item;
			return String(item);
		});
	}

	function sanitizeClaimAttempts(value, limit) {
		if (!Array.isArray(value)) return [];
		return value.slice(-Math.max(1, limit || MAX_ATTEMPTS_PER_MAIL)).map(attempt => cloneJson(attempt, null)).filter(Boolean);
	}

	function sanitizeLocalArchiveRecord(source, targetAccountId) {
		if (!source || source.mid == null || String(source.accountId || "") !== targetAccountId) return null;
		const attachment = source.attachment || {};
		const attachmentType = Number(source.attachmentType || sanitizeImportedArray(attachment.type)[0]) || 0;
		const attempts = sanitizeClaimAttempts(source.claimAttempts, MAX_ATTEMPTS_PER_MAIL);
		return {
			version: 1,
			accountId: targetAccountId,
			mid: String(source.mid),
			category: source.category === "friend" ? "friend" : "system",
			title: String(source.title || "未命名邮件"),
			content: String(source.content || ""),
			type: Number(source.type) || 0,
			fromUserName: String(source.fromUserName || ""),
			sendtime: Number(source.sendtime) || 0,
			originalEndtime: Number(source.originalEndtime) || 0,
			capturedAt: Number(source.capturedAt) || Date.now(),
			lastSeenAt: Number(source.lastSeenAt) || 0,
			presentInLiveList: false,
			jsonAutoClaim: true,
			autoWhitelistSource: String(source.autoWhitelistSource || "").slice(0, 64),
			autoWhitelistedAt: Number(source.autoWhitelistedAt) || 0,
			hasAttachment: Boolean(source.hasAttachment || source.attachment),
			getedAtCapture: Boolean(source.getedAtCapture),
			lastKnownGeted: Boolean(source.lastKnownGeted),
			lastConfirmedSuccessAttempt: latestExplicitSuccessAttempt(source),
			attachmentType: attachmentType,
			attachment: {
				id: sanitizeImportedArray(attachment.id),
				ctn: sanitizeImportedArray(attachment.ctn),
				key: sanitizeImportedArray(attachment.key),
				type: sanitizeImportedArray(attachment.type),
				opt: sanitizeImportedArray(attachment.opt)
			},
			claimRoute: getClaimRoute(attachmentType),
			claimAttempts: attempts,
			lastClaimResult: String(source.lastClaimResult || (attempts.length ? attempts[attempts.length - 1].state : "never-requested"))
		};
	}

	function sanitizeCrossRecord(source, originAccountId, importedIntoAccountId, importedAt, sourceExportedAt) {
		if (!source || source.mid == null || String(source.accountId || "") !== originAccountId) return null;
		const attachment = source.attachment || {};
		const attachmentType = Number(source.attachmentType || sanitizeImportedArray(attachment.type)[0]) || 0;
		return {
			version: 1,
			crossAccountTest: true,
			originAccountId: originAccountId,
			importedIntoAccountId: importedIntoAccountId,
			importedAt: importedAt,
			sourceExportedAt: Number(sourceExportedAt) || 0,
			accountId: originAccountId,
			mid: String(source.mid),
			category: source.category === "friend" ? "friend" : "system",
			title: String(source.title || "未命名邮件"),
			content: String(source.content || ""),
			type: Number(source.type) || 0,
			fromUserName: String(source.fromUserName || ""),
			sendtime: Number(source.sendtime) || 0,
			originalEndtime: Number(source.originalEndtime) || 0,
			capturedAt: Number(source.capturedAt) || 0,
			hasAttachment: Boolean(source.hasAttachment || source.attachment),
			getedAtCapture: Boolean(source.getedAtCapture),
			lastKnownGeted: Boolean(source.lastKnownGeted),
			attachmentType: attachmentType,
			attachment: {
				id: sanitizeImportedArray(attachment.id),
				ctn: sanitizeImportedArray(attachment.ctn),
				key: sanitizeImportedArray(attachment.key),
				type: sanitizeImportedArray(attachment.type),
				opt: sanitizeImportedArray(attachment.opt)
			},
			claimRoute: getClaimRoute(attachmentType),
			sourceClaimAttemptCount: Array.isArray(source.claimAttempts) ? source.claimAttempts.length : 0,
			claimAttempts: [],
			lastClaimResult: "never-requested"
		};
	}

	function mergeAttemptLists(current, incoming, limit) {
		const byId = new Map();
		for (const attempt of (current || []).concat(incoming || [])) {
			if (!attempt) continue;
			const key = String(attempt.id || [attempt.route, attempt.requestedAt, attempt.state].join(":"));
			byId.set(key, attempt);
		}
		return Array.from(byId.values())
			.sort((a, b) => Number(a.requestedAt || 0) - Number(b.requestedAt || 0))
			.slice(-Math.max(1, limit || MAX_ATTEMPTS_PER_MAIL));
	}

	function importSameAccountBackup(input) {
		if (!resolveRuntimeObjects()) throw new Error(lastResult);
		const detected = detectAccountId();
		if (!detected) throw new Error("current-account-unavailable");
		if (detected !== accountId) loadAccount(detected);
		let payload = input;
		if (typeof payload === "string") {
			try { payload = JSON.parse(payload); } catch (error) { throw new Error("invalid-json"); }
		}
		if (!payload || typeof payload !== "object" || !Array.isArray(payload.records)) throw new Error("invalid-archive-format");
		const backupAccountId = String(payload.accountId || "").trim();
		if (!backupAccountId) throw new Error("missing-backup-account-id");
		if (backupAccountId !== accountId) throw new Error("backup-account-mismatch:" + backupAccountId + "->" + accountId);
		if (payload.records.length > MAX_CROSS_IMPORT_RECORDS) throw new Error("too-many-records:" + payload.records.length);

		let previousWhitelistDisabledCount = 0;
		for (const record of records) {
			if (!record || record.jsonAutoClaim !== true) continue;
			record.jsonAutoClaim = false;
			previousWhitelistDisabledCount += 1;
		}
		let localImportedCount = 0;
		let localMergedCount = 0;
		let restoredTombstoneCount = 0;
		let skippedCount = 0;
		for (const source of payload.records) {
			const incoming = sanitizeLocalArchiveRecord(source, accountId);
			if (!incoming || !incoming.hasAttachment) {
				skippedCount += 1;
				continue;
			}
			// “导入本账号 JSON”是用户主动恢复操作：允许恢复用户自己删除过的 MID；
			// 内置固定排除项仍继续生效，自动扫描也仍受墓碑保护。
			if (userExcludedMids.delete(incoming.mid)) restoredTombstoneCount += 1;
			if (isArchiveMidSuppressed(accountId, incoming.mid)) {
				skippedCount += 1;
				continue;
			}
			const existing = recordsByMid.get(incoming.mid);
			if (!existing) {
				records.push(incoming);
				recordsByMid.set(incoming.mid, incoming);
				localImportedCount += 1;
				continue;
			}
			existing.claimAttempts = mergeAttemptLists(existing.claimAttempts, incoming.claimAttempts, MAX_ATTEMPTS_PER_MAIL);
			if ((!existing.attachment || !existing.attachment.key || !existing.attachment.key.length) && incoming.attachment.key.length) {
				existing.attachment = incoming.attachment;
				existing.attachmentType = incoming.attachmentType;
				existing.claimRoute = incoming.claimRoute;
			}
			if (!existing.originalEndtime) existing.originalEndtime = incoming.originalEndtime;
			if (!existing.capturedAt || incoming.capturedAt < existing.capturedAt) existing.capturedAt = incoming.capturedAt;
			if (!existing.presentInLiveList) existing.lastKnownGeted = incoming.lastKnownGeted;
			existing.jsonAutoClaim = true;
			if (existing.claimAttempts.length) existing.lastClaimResult = existing.claimAttempts[existing.claimAttempts.length - 1].state || incoming.lastClaimResult;
			localMergedCount += 1;
		}

		let crossImportedCount = 0;
		for (const source of Array.isArray(payload.crossAccountTests) ? payload.crossAccountTests.slice(0, MAX_CROSS_IMPORT_RECORDS) : []) {
			const originAccountId = String(source && source.originAccountId || "").trim();
			if (!originAccountId || originAccountId === accountId || String(source.importedIntoAccountId || "") !== accountId) {
				skippedCount += 1;
				continue;
			}
			const key = crossRecordKey(originAccountId, source.mid);
			const incoming = sanitizeCrossRecord(source, originAccountId, accountId, Number(source.importedAt) || Date.now(), source.sourceExportedAt);
			if (!incoming) {
				skippedCount += 1;
				continue;
			}
			incoming.claimAttempts = sanitizeClaimAttempts(source.claimAttempts, 1);
			incoming.lastClaimResult = String(source.lastClaimResult || (incoming.claimAttempts.length ? incoming.claimAttempts[0].state : "never-requested"));
			const existing = crossRecordsByKey.get(key);
			if (!existing) {
				crossRecords.push(incoming);
				crossRecordsByKey.set(key, incoming);
				crossImportedCount += 1;
			} else if (!existing.claimAttempts.length && incoming.claimAttempts.length) {
				existing.claimAttempts = incoming.claimAttempts;
				existing.lastClaimResult = incoming.lastClaimResult;
			}
		}

		const importedLedger = payload.crossAccountAttemptLedger;
		if (importedLedger && typeof importedLedger === "object" && !Array.isArray(importedLedger)) {
			for (const [key, attempt] of Object.entries(importedLedger)) {
				if (!attempt || String(attempt.currentAccountId || "") !== accountId || String(attempt.originAccountId || "") === accountId) continue;
				if (!crossAttemptLedger[key]) crossAttemptLedger[key] = cloneJson(attempt, attempt);
			}
		}
		for (const record of crossRecords) {
			const ledgerAttempt = crossAttemptLedger[crossRecordKey(record.originAccountId, record.mid)];
			if (!record.claimAttempts.length && ledgerAttempt) {
				record.claimAttempts = [cloneJson(ledgerAttempt, ledgerAttempt)];
				record.lastClaimResult = record.claimAttempts[0].state || "attempt-recorded";
			}
		}

		archiveCount = records.length;
		persistAll();
		const jsonWhitelistCount = records.filter(record => record && record.jsonAutoClaim === true).length;
		lastResult = "json-whitelist-replaced:" + jsonWhitelistCount + ",imported:" + localImportedCount + ",merged:" + localMergedCount + ",restored-tombstones:" + restoredTombstoneCount + ",skipped:" + skippedCount;
		renderPanel();
		return { accountId, localImportedCount, localMergedCount, crossImportedCount, skippedCount, jsonWhitelistCount, previousWhitelistDisabledCount, restoredTombstoneCount };
	}

	function importCrossAccountArchive(input) {
		if (!resolveRuntimeObjects()) throw new Error(lastResult);
		const detected = detectAccountId();
		if (!detected) throw new Error("current-account-unavailable");
		if (detected !== accountId) loadAccount(detected);
		let payload = input;
		if (typeof payload === "string") {
			try { payload = JSON.parse(payload); } catch (error) { throw new Error("invalid-json"); }
		}
		if (!payload || typeof payload !== "object" || !Array.isArray(payload.records)) throw new Error("invalid-archive-format");
		const originAccountId = String(payload.accountId || "").trim();
		if (!originAccountId) throw new Error("missing-origin-account-id");
		if (originAccountId === accountId) throw new Error("origin-and-current-account-must-differ");
		if (payload.records.length > MAX_CROSS_IMPORT_RECORDS) throw new Error("too-many-records:" + payload.records.length);

		const importedAt = Date.now();
		let importedCount = 0;
		let duplicateCount = 0;
		let skippedCount = 0;
		for (const source of payload.records) {
			const record = sanitizeCrossRecord(source, originAccountId, accountId, importedAt, payload.exportedAt);
			if (!record || !record.hasAttachment) {
				skippedCount += 1;
				continue;
			}
			const key = crossRecordKey(originAccountId, record.mid);
			if (crossRecordsByKey.has(key)) {
				duplicateCount += 1;
				continue;
			}
			if (crossAttemptLedger[key]) {
				record.claimAttempts = [cloneJson(crossAttemptLedger[key], crossAttemptLedger[key])];
				record.lastClaimResult = record.claimAttempts[0].state || "attempt-recorded";
			}
			crossRecords.push(record);
			crossRecordsByKey.set(key, record);
			importedCount += 1;
		}
		persistCross();
		lastResult = "cross-imported:" + importedCount;
		renderPanel();
		return { originAccountId, currentAccountId: accountId, importedCount, duplicateCount, skippedCount };
	}

	function getMailLists() {
		if (!mailManager) return { system: [], friend: [] };
		let system = [];
		let friend = [];
		try {
			system = typeof mailManager.GetSystemMailList === "function" ? mailManager.GetSystemMailList() : mailManager.systemMailList;
			friend = typeof mailManager.GetFriendMailList === "function" ? mailManager.GetFriendMailList() : mailManager.friendMailList;
		} catch (error) {
			lastError = "mail-list:" + String(error && error.message || error);
		}
		return {
			system: Array.isArray(system) ? system : [],
			friend: Array.isArray(friend) ? friend : []
		};
	}

	function getServerNow() {
		for (const field of ["LocalServerTime", "ServerTime"]) {
			try {
				const value = Number(timerManager && timerManager[field]);
				if (Number.isFinite(value) && value > 0) return Math.floor(value);
			} catch (error) {}
		}
		return Math.floor(Date.now() / 1000);
	}

	function createArchiveRecord(mail, category, now) {
		const attachmentType = getAttachmentType(mail);
		return {
			version: 1,
			accountId: accountId,
			mid: String(mail.mid),
			category: category,
			title: String(mail.title || "未命名邮件"),
			content: String(mail.content || ""),
			type: Number(mail.type) || 0,
			fromUserName: String(mail.fromUserName || ""),
			sendtime: Number(mail.sendtime) || 0,
			originalEndtime: Number(mail.endtime) || 0,
			capturedAt: now,
			lastSeenAt: now,
			presentInLiveList: true,
			jsonAutoClaim: false,
			autoWhitelistSource: "",
			autoWhitelistedAt: 0,
			hasAttachment: mailHasAttachment(mail),
			getedAtCapture: Boolean(mail.Geted),
			lastKnownGeted: Boolean(mail.Geted),
			lastConfirmedSuccessAttempt: null,
			attachmentType: attachmentType,
			attachment: {
				id: readAttachmentField(mail.attachment, "id"),
				ctn: readAttachmentField(mail.attachment, "ctn"),
				key: readAttachmentField(mail.attachment, "key"),
				type: readAttachmentField(mail.attachment, "type"),
				opt: readAttachmentField(mail.attachment, "opt")
			},
			claimRoute: getClaimRoute(attachmentType),
			claimAttempts: [],
			lastClaimResult: "never-requested"
		};
	}

	function updateArchiveRecord(record, mail, category, now) {
		let changed = false;
		if (now - Number(record.lastSeenAt || 0) >= LAST_SEEN_PERSIST_INTERVAL_MS) {
			record.lastSeenAt = now;
			changed = true;
		}
		if (!record.presentInLiveList) {
			record.presentInLiveList = true;
			changed = true;
		}
		if (record.category !== category) {
			record.category = category;
			changed = true;
		}
		if (record.lastKnownGeted !== Boolean(mail.Geted)) {
			record.lastKnownGeted = Boolean(mail.Geted);
			changed = true;
		}
		if (!record.title && mail.title) { record.title = String(mail.title); changed = true; }
		if (!record.content && mail.content) { record.content = String(mail.content); changed = true; }
		if (!record.originalEndtime) { record.originalEndtime = Number(mail.endtime) || 0; changed = true; }
		if (!record.sendtime) { record.sendtime = Number(mail.sendtime) || 0; changed = true; }
		if (!record.fromUserName && mail.fromUserName) { record.fromUserName = String(mail.fromUserName); changed = true; }
		if (!record.attachment || !record.attachment.key || !record.attachment.key.length) {
			const fresh = createArchiveRecord(mail, category, now);
			record.attachment = fresh.attachment;
			record.attachmentType = fresh.attachmentType;
			record.claimRoute = fresh.claimRoute;
			changed = true;
		}
		return changed;
	}

	function archiveLoadedMails() {
		if (!accountId || !mailManager) return 0;
		const lists = getMailLists();
		const now = Date.now();
		let added = 0;
		let changed = false;
		liveMailsByMid = new Map();
		const seenAttachmentMids = new Set();

		for (const entry of [
			{ category: "system", mails: lists.system },
			{ category: "friend", mails: lists.friend }
		]) {
			for (const mail of entry.mails) {
				if (!mail || mail.mid == null) continue;
				const mid = String(mail.mid);
				liveMailsByMid.set(mid, mail);
				if (isArchiveMidSuppressed(accountId, mid)) continue;
				if (!mailHasAttachment(mail)) continue;
				seenAttachmentMids.add(mid);
				let record = recordsByMid.get(mid);
				if (!record) {
					record = createArchiveRecord(mail, entry.category, now);
					records.push(record);
					recordsByMid.set(mid, record);
					added += 1;
					changed = true;
				} else {
					changed = updateArchiveRecord(record, mail, entry.category, now) || changed;
				}
				changed = autoWhitelistLiveRecord(record, mail, now) || changed;
			}
		}
		for (const record of records) {
			if (!seenAttachmentMids.has(record.mid) && record.presentInLiveList) {
				record.presentInLiveList = false;
				changed = true;
			}
		}

		archiveCount = records.length;
		if (changed) persist();
		lastResult = added ? "archived:" + added : "ready:no-new-attachment-mail";
		return added;
	}

	function ensureArchiveAccountReady() {
		if (!resolveRuntimeObjects()) throw new Error(lastResult || "runtime-not-ready");
		const detected = detectAccountId();
		if (!detected) throw new Error("current-account-unavailable");
		if (detected !== accountId) loadAccount(detected);
		return detected;
	}

	function normalizeManualAttachmentId(value) {
		const text = String(value == null ? "" : value).trim();
		if (!/^\d{1,16}$/.test(text) || Number(text) <= 0 || !Number.isSafeInteger(Number(text))) return 0;
		return Number(text);
	}

	function upsertManualArchiveRecord(input) {
		ensureArchiveAccountReady();
		const source = input && typeof input === "object" ? input : {};
		const mid = normalizeArchiveMid(source.mid);
		if (!mid) throw new Error("MID 必须是 1～32 位数字");
		const title = String(source.title || source.name || "").trim().slice(0, 100);
		if (!title) throw new Error("请填写邮件名称");
		const attachmentType = Number(source.attachmentType) === ITEM_ATTACHMENT ? ITEM_ATTACHMENT : GIFT_ATTACHMENT;
		const attachmentId = normalizeManualAttachmentId(source.giftId != null ? source.giftId : source.attachmentId);
		if (!attachmentId) throw new Error(attachmentType === GIFT_ATTACHMENT ? "请填写有效 GiftID" : "请填写有效道具 ID");
		const count = Math.max(1, Math.min(999999, Math.floor(Number(source.count) || 1)));
		const verificationKey = String(source.key || "").trim().slice(0, 256);
		if (attachmentType === ITEM_ATTACHMENT && !verificationKey) throw new Error("道具附件必须填写验证码 Key");
		const now = Date.now();
		let record = recordsByMid.get(mid);
		const created = !record;
		if (!record) {
			record = {
				version: 1,
				accountId: accountId,
				mid: mid,
				category: "system",
				content: "",
				type: 3,
				fromUserName: "",
				sendtime: Math.floor(now / 1000),
				originalEndtime: 0,
				capturedAt: now,
				lastSeenAt: 0,
				presentInLiveList: false,
				getedAtCapture: false,
				lastKnownGeted: false,
				lastConfirmedSuccessAttempt: null,
				claimAttempts: [],
				lastClaimResult: "never-requested"
			};
			records.push(record);
			recordsByMid.set(mid, record);
		}
		record.title = title;
		record.content = String(source.content || record.content || "").slice(0, 2000);
		record.attachmentType = attachmentType;
		record.attachment = {
