		}
		persist();
		return Promise.resolve(cloneJson(attempt, {}));
	}

	function claimCrossAccountRecord(originAccountId, mid, options) {
		options = options || {};
		if (!resolveRuntimeObjects()) return Promise.reject(new Error(lastResult));
		const key = crossRecordKey(originAccountId, mid);
		const record = crossRecordsByKey.get(key);
		const validationError = validateCrossAccountClaim(record);
