				const friendName = record.fromUserName && record.fromUserName !== "系统未知好友" ? record.fromUserName : "";
				attempt.request = { veriCode: verificationKey, mid: record.mid, friendNickName: friendName };
				installClaimProtocolListener(record, attempt);
				attempt.sentAt = Date.now();
				(window.__SGSOL_MOBILE_PLATFORM__.assertAction(), mailManager.SendClientDbsGetgmawardReq(verificationKey, record.mid, friendName));
			} else {
				const giftId = Number(record.attachment.id[0]);
				const verificationKey = String(record.attachment.key && record.attachment.key[0] || "");
				attempt.request = { giftId: giftId, key: verificationKey, mid: record.mid };
				installClaimProtocolListener(record, attempt);
				attempt.sentAt = Date.now();
