	function autoGiftSleep(milliseconds) {
		return new Promise(resolve => window.setTimeout(resolve, Math.max(0, milliseconds)));
	}

	function setAutoGiftEnabled(enabled) {
		if (!accountId) throw new Error("current-account-unavailable");
		autoGiftEnabled = Boolean(enabled);
		try {
			localStorage.setItem(autoGiftEnabledStorageKey(accountId), autoGiftEnabled ? "true" : "false");
		} catch (error) {
			lastError = "auto-gift-setting-save:" + String(error && error.message || error);
		}
		lastAutoGiftResult = autoGiftEnabled ? "waiting:archive" : "disabled";
		renderPanel();
		if (autoGiftEnabled) startAutoGiftQueue();
		return autoGiftEnabled;
	}

	function settleAutoGiftAttempt(record, attempt, timeoutKind) {
		if (!attempt || attempt.state !== "waiting-response") return attempt && attempt.state || "attempt-unavailable";
		attempt.state = "no-response-timeout";
		attempt.timeoutKind = String(timeoutKind || "final-response-wait-limit");
		attempt.respondedAt = Date.now();
		attempt.responseMs = attempt.respondedAt - Number(attempt.sentAt || attempt.requestedAt);
		attempt.inventoryAfter = snapshotRelevantInventory(record);
		attempt.inventoryDelta = compareInventory(attempt.inventoryBefore, attempt.inventoryAfter);
		record.lastClaimResult = attempt.state;
		const timeoutId = pendingTimeouts.get(attempt.id);
		if (timeoutId) window.clearTimeout(timeoutId);
		pendingTimeouts.delete(attempt.id);
		removeClaimProtocolListener(attempt.id, "response-timeout");
		return attempt.state;
	}

	async function waitForAllAutoGiftAttempts(pendingEntries) {
		const deadlineAt = Date.now() + Math.max(0, AUTO_GIFT_FINAL_RESPONSE_WAIT_MS);
		while (!stopped && pendingEntries.some(entry => entry.attempt && entry.attempt.state === "waiting-response") && Date.now() < deadlineAt) {
			await autoGiftSleep(Math.min(AUTO_GIFT_POLL_MS, Math.max(0, deadlineAt - Date.now())));
		}
		autoGiftFinalWaitTimedOut = pendingEntries.some(entry => entry.attempt && entry.attempt.state === "waiting-response");
		if (autoGiftFinalWaitTimedOut && !stopped) {
			for (const entry of pendingEntries) settleAutoGiftAttempt(entry.record, entry.attempt, "final-response-wait-limit");
			persist();
			renderPanel();
		}
	}

	function isAutoGiftFailure(state) {
		return state === "request-error" || state === "no-response-timeout" || String(state || "").startsWith("server-rejected:");
	}

	function autoGiftAttachmentIdentity(record) {
		const rawId = record && record.attachment && Array.isArray(record.attachment.id)
			? record.attachment.id[0]
			: null;
		const attachmentId = rawId == null ? "" : String(rawId).trim();
		return {
			attachmentId,
			attachmentKind: record && record.claimRoute === "single-gift" ? "GiftID" : "道具ID"
		};
	}

	function autoGiftAttemptDiagnostics(attempt) {
		const listener = attempt && attempt.responseListener || {};
		return {
			responseCaptureSource: String(attempt && attempt.responseCaptureSource || ""),
			responseProtocolId: attempt && attempt.responseProtocolId != null ? Number(attempt.responseProtocolId) : null,
			responseMid: String(attempt && attempt.responseMid || ""),
			responseGiftId: attempt && attempt.responseGiftId != null ? Number(attempt.responseGiftId) : null,
			listenerProtocolId: listener.protocolId == null ? null : Number(listener.protocolId),
			listenerRegistered: listener.registered === true,
			listenerReceivedCount: Number(listener.receivedCount) || 0,
			listenerUnmatchedCount: Number(listener.unmatchedCount) || 0,
			listenerLastReceivedMid: String(listener.lastReceivedMid || ""),
			listenerLastReceivedGiftId: listener.lastReceivedGiftId == null ? null : Number(listener.lastReceivedGiftId),
			listenerLastReceivedResult: listener.lastReceivedResult == null ? null : Number(listener.lastReceivedResult),
			listenerLastUnmatchedReason: String(listener.lastUnmatchedReason || ""),
			listenerError: String(listener.error || "")
		};
	}

	function findNextAutoGiftRecord() {
		return records.find(record =>
			record &&
			record.accountId === accountId &&
			record.jsonAutoClaim === true &&
			["single-gift", "dbs-item"].includes(record.claimRoute) &&
			!autoGiftProcessedMids.has(record.mid)
		) || null;
	}

	function makeAutoGiftQueueResult(extra) {
		return Object.assign({
			accountId: accountId,
			processed: autoGiftCompletedCount,
			failed: autoGiftFailedCount,
			result: lastAutoGiftResult,
			finalWaitTimedOut: autoGiftFinalWaitTimedOut,
			finalResponseWaitMs: AUTO_GIFT_FINAL_RESPONSE_WAIT_MS,
			processedMids: Array.from(autoGiftProcessedMids),
			claimResults: cloneJson(autoGiftRunResults, [])
		}, extra || {});
	}

	function finalizeAutoGiftQueue() {
		if (autoGiftFinalizedResult) return Promise.resolve(cloneJson(autoGiftFinalizedResult, autoGiftFinalizedResult));
		if (autoGiftFinalizePromise) return autoGiftFinalizePromise;
		autoGiftFinalizePromise = (async function finalizeSentAutoGiftQueue() {
			if (autoGiftRunPromise) await autoGiftRunPromise;
			if (autoGiftPendingEntries.length && !stopped) {
				lastAutoGiftResult = "waiting:remaining-responses-up-to-" + AUTO_GIFT_FINAL_RESPONSE_WAIT_MS;
				renderPanel();
				await waitForAllAutoGiftAttempts(autoGiftPendingEntries);
			}
			for (const entry of autoGiftPendingEntries) {
				const attempt = entry.attempt;
				const state = String(attempt && attempt.state || "attempt-unavailable");
				autoGiftRunResults.push({
					mid: String(entry.record.mid),
					route: entry.record.claimRoute,
					...autoGiftAttachmentIdentity(entry.record),
					state: state,
					attemptId: String(attempt && attempt.id || ""),
					resultCode: attempt && attempt.resultCode != null && Number.isFinite(Number(attempt.resultCode)) ? Number(attempt.resultCode) : null,
					requestedAt: Number(attempt && attempt.requestedAt) || 0,
					sentAt: Number(attempt && attempt.sentAt) || 0,
					respondedAt: Number(attempt && attempt.respondedAt) || 0,
					responseMs: Number(attempt && attempt.responseMs) || 0,
					...autoGiftAttemptDiagnostics(attempt)
				});
				if (isAutoGiftFailure(state)) autoGiftFailedCount += 1;
			}
			autoGiftCurrentMid = "";
			if (!records.some(record => record.jsonAutoClaim === true && ["single-gift", "dbs-item"].includes(record.claimRoute))) lastAutoGiftResult = "ready:no-json-whitelist-attachments";
			else if (autoGiftFinalWaitTimedOut) lastAutoGiftResult = "complete:final-wait-timeout-" + AUTO_GIFT_FINAL_RESPONSE_WAIT_MS + ",processed-" + autoGiftProcessedThisRun;
			else lastAutoGiftResult = "complete:processed-" + autoGiftProcessedThisRun + ",session-total-" + autoGiftCompletedCount + ",failed-" + autoGiftFailedCount;
		autoGiftFinalizedResult = makeAutoGiftQueueResult({ deferred: false });
			appendAutoGiftCycleTelemetry();
			autoGiftDeferFinalWait = false;
			return cloneJson(autoGiftFinalizedResult, autoGiftFinalizedResult);
		})().finally(() => {
			autoGiftFinalizePromise = null;
			renderPanel();
		});
		return autoGiftFinalizePromise;
	}

	function startAutoGiftQueue(options) {
		const deferFinalWait = options && options.deferFinalWait === true || autoGiftDeferFinalWait;
		if (!autoGiftEnabled || stopped || !accountId || autoGiftSessionAccountId !== accountId) return autoGiftRunPromise || Promise.resolve(false);
		if (autoGiftRunPromise) return deferFinalWait ? autoGiftRunPromise : autoGiftRunPromise.then(() => finalizeAutoGiftQueue());
		if (!findNextAutoGiftRecord()) {
			if (!deferFinalWait && autoGiftPendingEntries.length) return finalizeAutoGiftQueue();
			lastAutoGiftResult = records.some(record => record.jsonAutoClaim === true && ["single-gift", "dbs-item"].includes(record.claimRoute))
				? "sent:session-total-" + autoGiftCompletedCount
				: "ready:no-archived-gifts";
			renderPanel();
			return Promise.resolve(true);
		}
		const runAccountId = accountId;
		autoGiftRunPromise = (async function sendAutoGiftQueue() {
			autoGiftFinalWaitTimedOut = false;
			lastAutoGiftResult = "running:send-phase";
			renderPanel();
			while (autoGiftEnabled && !stopped && accountId === runAccountId) {
				const record = findNextAutoGiftRecord();
				if (!record) break;
				autoGiftProcessedMids.add(record.mid);
				autoGiftCurrentMid = record.mid;
				lastAutoGiftResult = "claiming:" + record.mid;
				renderPanel();
				const beforeAttemptCount = record.claimAttempts.length;
				try {
					await claimArchivedMail(record.mid, { skipConfirmation: true, requireJsonWhitelist: true, deferResponseTimeout: true });
					const attempt = record.claimAttempts[beforeAttemptCount] || record.claimAttempts[record.claimAttempts.length - 1];
					autoGiftPendingEntries.push({ record: record, attempt: attempt });
					autoGiftCompletedCount += 1;
					autoGiftProcessedThisRun += 1;
					lastAutoGiftResult = "sent:" + record.mid;
				} catch (error) {
					autoGiftFailedCount += 1;
					lastError = String(error && error.message || error);
					const attempt = record.claimAttempts[beforeAttemptCount] || null;
					autoGiftRunResults.push({
						mid: String(record.mid),
						route: record.claimRoute,
						...autoGiftAttachmentIdentity(record),
						state: String(attempt && attempt.state || "request-error"),
						attemptId: String(attempt && attempt.id || ""),
						resultCode: attempt && attempt.resultCode != null && Number.isFinite(Number(attempt.resultCode)) ? Number(attempt.resultCode) : null,
						requestedAt: Number(attempt && attempt.requestedAt) || 0,
						sentAt: Number(attempt && attempt.sentAt) || 0,
						respondedAt: Number(attempt && attempt.respondedAt) || 0,
						responseMs: Number(attempt && attempt.responseMs) || 0,
						...autoGiftAttemptDiagnostics(attempt),
						error: lastError
					});
					lastAutoGiftResult = "error:" + record.mid + ":" + lastError;
				}
				autoGiftCurrentMid = "";
				renderPanel();
				if (autoGiftEnabled && !stopped && accountId === runAccountId && findNextAutoGiftRecord()) await autoGiftSleep(AUTO_GIFT_BETWEEN_MS);
			}
			lastAutoGiftResult = "sent:all-requests;responses-collecting-in-background";
			return true;
		})().finally(() => {
			autoGiftRunPromise = null;
			renderPanel();
		});
		return deferFinalWait ? autoGiftRunPromise : autoGiftRunPromise.then(() => finalizeAutoGiftQueue());
	}

	function whenAutoGiftIdle() {
		return autoGiftFinalizePromise || autoGiftRunPromise || Promise.resolve(true);
	}

	async function finalizeAutoGiftQueueAfterLiveMail() {
		try {
			return await finalizeAutoGiftQueue();
		} finally {
			autoGiftEnabled = false;
			autoGiftDeferFinalWait = false;
			try { localStorage.setItem(autoGiftEnabledStorageKey(accountId), "false"); } catch (error) {}
		}
	}

	async function runAutoGiftQueueAfterLiveMail(options) {
		if (stopped) throw new Error("script-stopped");
		scan(false);
		if (!accountId || autoGiftSessionAccountId !== accountId) throw new Error("current-account-unavailable");
		const deferFinalWait = options && options.deferFinalWait === true;
		if (autoGiftFinalizedResult && !autoGiftRunPromise && !autoGiftFinalizePromise && !autoGiftDeferFinalWait) {
			// 上一轮已经完整结束；新一次调用必须重新发送本轮 JSON 白名单。
			autoGiftFinalizedResult = null;
		}
		if (!autoGiftRunPromise && !autoGiftFinalizePromise) {
			// 每轮登录都重新处理持久化 JSON 白名单；这个集合只用于防止同一轮重复发送。
			autoGiftProcessedMids = new Set();
			autoGiftRunResults = [];
			autoGiftPendingEntries = [];
			autoGiftProcessedThisRun = 0;
			autoGiftCompletedCount = 0;
			autoGiftFailedCount = 0;
			autoGiftFinalWaitTimedOut = false;
			autoGiftFinalizedResult = null;
		}
		autoGiftDeferFinalWait = deferFinalWait;
		autoGiftEnabled = true;
		lastAutoGiftResult = "starting:after-live-mail";
		try {
			await startAutoGiftQueue({ deferFinalWait: deferFinalWait });
			if (deferFinalWait) return makeAutoGiftQueueResult({ deferred: true });
			return await finalizeAutoGiftQueue();
		} catch (error) {
			autoGiftEnabled = false;
			autoGiftDeferFinalWait = false;
			throw error;
		} finally {
			if (!deferFinalWait) {
				autoGiftEnabled = false;
				autoGiftDeferFinalWait = false;
				try { localStorage.setItem(autoGiftEnabledStorageKey(accountId), "false"); } catch (error) {}
			}
		}
	}

	function formatBeijing(timestamp, seconds) {
		const milliseconds = seconds ? Number(timestamp) * 1000 : Number(timestamp);
		if (!Number.isFinite(milliseconds) || milliseconds <= 0) return "未知";
		try {
			return new Intl.DateTimeFormat("zh-CN", {
				timeZone: "Asia/Shanghai",
				year: "numeric", month: "2-digit", day: "2-digit",
				hour: "2-digit", minute: "2-digit", second: "2-digit",
				hour12: false
			}).format(new Date(milliseconds));
		} catch (error) {
			return new Date(milliseconds).toLocaleString();
		}
	}

	function translateResult(result) {
		if (!result || result === "never-requested") return "尚未尝试";
		if (result === "waiting-response") return "等待服务器回包";
		if (result === "server-accepted") return "服务器接受请求";
		if (result === "server-reported-already-handled") return "服务器表示已处理";
		if (result === "server-reported-already-claimed") return "服务器表示已经领取";
		if (result === "no-response-timeout") return "12 秒内未捕获回包";
		if (result.startsWith("server-rejected:")) return "服务器拒绝，结果码 " + result.split(":")[1];
		if (result.startsWith("request-error")) return "请求异常";
		return result;
	}

	function attachmentSummary(record) {
		const ids = record.attachment && record.attachment.id || [];
		const counts = record.attachment && record.attachment.ctn || [];
		if (record.claimRoute === "single-gift") return "礼包 ID " + (ids[0] == null ? "未知" : ids[0]);
		if (record.claimRoute === "dbs-item") {
			return ids.map((id, index) => String(id) + " x" + (counts[index] == null ? "?" : counts[index])).join("，") || "道具信息缺失";
		}
		return "未知附件类型 " + record.attachmentType;
	}

	function addText(parent, className, text) {
