			const live = document.createElement("span");
			live.className = "h5mca-badge " + (record.presentInLiveList ? "is-live" : "is-archived");
			live.textContent = record.presentInLiveList ? "正式列表中" : "仅归档保留";
			head.appendChild(live);
			card.appendChild(head);

			const expired = record.originalEndtime > 0 && serverNow >= record.originalEndtime;
			addText(card, "h5mca-meta", "MID " + record.mid + " · " + (record.category === "friend" ? "好友邮件" : "系统邮件"));
			addText(card, "h5mca-meta", "原过期时间：" + formatBeijing(record.originalEndtime, true) + "（" + (expired ? "已到期" : "尚未到期") + "）");
			addText(card, "h5mca-meta", "领取标记：" + (record.lastKnownGeted ? "游戏显示已领取，可测试重复请求" : "游戏显示未领取"));
			addText(card, "h5mca-meta", "附件：" + attachmentSummary(record));
			addText(card, "h5mca-result", "最近结果：" + translateResult(record.lastClaimResult));

			const actions = document.createElement("div");
			actions.className = "h5mca-actions";
