        if (nickname) return 'name:' + nickname;
        const accountId = String(friend && friend.friendId || '').trim();
        if (isOfficerAccountId(accountId)) return 'account:' + accountId;
        return '';
    }

    function officerFriendMatchesTarget(friend, target) {
        if (!friend || !target) return false;
        const targetId = String(target.id || '').trim();
        if (targetId && officerFriendStableKey(friend) === targetId) return true;
        const targetNickname = normalizedOfficerNickname(target.nickname);
        // 保存过昵称后不再退回可能碰撞的一字节 friendID。
        if (targetNickname) return normalizedOfficerNickname(friend.nickname) === targetNickname;
        if (isOfficerAccountId(targetId) && String(friend.friendId || '') === targetId) return true;
        return !!targetId && String(friend.legacyFriendId || '') === targetId;
    }

    function canonicalOfficerWorkerPeers(tab = readOfficerLinkTab()) {
        const byAccountId = new Map();
        for (const peer of tab.bridgePeers || []) {
            if (!peer || peer.role !== 'worker' || !isOfficerAccountId(peer.accountId)) continue;
            const accountId = String(peer.accountId);
            const current = byAccountId.get(accountId);
            // 真实在线心跳优先于仅用于离线路由的历史绑定。
            if (!current || (current.knownBinding === true && peer.knownBinding !== true)) byAccountId.set(accountId, peer);
        }
        return Array.from(byAccountId.values());
    }

    function mergeOfficerKnownWorkerBindings(livePeers, knownBindings) {
        const bridgePeers = Array.isArray(livePeers) ? livePeers.slice() : [];
        const knownKeys = new Set(bridgePeers
            .filter((peer) => peer && peer.role === 'worker')
            .map((peer) => String(peer.accountId || '').trim())
            .filter(Boolean));
        for (const binding of Array.isArray(knownBindings) ? knownBindings : []) {
            const accountId = String(binding && binding.accountId || '').trim();
            const nickname = String(binding && binding.nickname || '').trim();
            if (!isOfficerAccountId(accountId) || !nickname || knownKeys.has(accountId)) continue;
            bridgePeers.push({
                peerId: 'known-worker-' + accountId,
                role: 'worker',
                accountId,
                nickname,
                officerLv: '',
                targetId: accountId,
                lastSeenAt: Number(binding.lastSeenAt) || 0,
                knownBinding: true
            });
            knownKeys.add(accountId);
        }
        return bridgePeers;
    }

    function resolveOfficerWorkerPeer(friend, target = null, tab = readOfficerLinkTab()) {
        const workers = canonicalOfficerWorkerPeers(tab);
        const selected = (tab.listenerTargets || []).filter((item) => item && item.id);
        const boundReceiverId = String(target && target.receiverId || '').trim();
        if (boundReceiverId) {
            const sharedBinding = selected.some((item) => item !== target
                && String(item.id || '') !== String(target && target.id || '')
                && String(item.receiverId || '').trim() === boundReceiverId);
            if (sharedBinding) return null;
            return workers.find((peer) => String(peer.accountId) === boundReceiverId) || null;
        }
        const nickname = normalizedOfficerNickname(friend && friend.nickname || target && target.nickname);
        if (nickname) {
            const nicknameMatches = workers.filter((peer) =>
                normalizedOfficerNickname(peer.nickname) === nickname);
            if (nicknameMatches.length === 1) {
                const candidate = nicknameMatches[0];
                const usedByOtherTarget = selected.some((item) => item !== target
                    && String(item.receiverId || '').trim() === String(candidate.accountId));
                if (!usedByOtherTarget) return candidate;
            }
        }
        if (selected.length === 1) {
            const friendAccountId = String(friend && friend.friendId || '').trim();
            if (isOfficerAccountId(friendAccountId)) {
                const accountMatch = workers.find((peer) => String(peer.accountId) === friendAccountId);
                if (accountMatch) return accountMatch;
            }
            if (workers.length === 1) return workers[0];
        }
        return null;
    }

    function resolveOfficerTargetReceiverId(friend, target = null, tab = readOfficerLinkTab()) {
        const boundReceiverId = String(target && target.receiverId || '').trim();
        if (isOfficerAccountId(boundReceiverId)) {
            const sharedBinding = (tab.listenerTargets || []).some((item) => item !== target
                && String(item && item.id || '') !== String(target && target.id || '')
                && item && item.id
                && String(item.receiverId || '').trim() === boundReceiverId);
            // 已明确且独占的绑定即使暂时离线，也可安全进入桥队列。
            if (!sharedBinding) return boundReceiverId;
        }
        const worker = resolveOfficerWorkerPeer(friend, target, tab);
        return worker ? String(worker.accountId || '').trim() : '';
    }

    function synchronizeOfficerTargetReceiverBindings(tab, friends) {
        const workers = canonicalOfficerWorkerPeers(tab);
        const workerById = new Map(workers.map((peer) => [String(peer.accountId), peer]));
        let changed = false;
        const targets = tab.listenerTargets.map((target) => {
            if (!target || !target.id) return target;
            const friend = (friends || []).find((item) => officerFriendMatchesTarget(item, target));
            const nickname = normalizedOfficerNickname(friend && friend.nickname || target.nickname);
            const exactWorkers = nickname
                ? workers.filter((peer) => normalizedOfficerNickname(peer.nickname) === nickname)
                : [];
            const exactReceiverId = exactWorkers.length === 1 ? String(exactWorkers[0].accountId) : '';
            const receiverId = String(target.receiverId || '').trim();
            if (target.receiverBindingManual === true || !exactReceiverId || exactReceiverId === receiverId) return target;
            changed = true;
            return {
                ...target,
                receiverId: exactReceiverId,
                receiverBindingManual: false,
                lastLv: '',
                lv1Latched: false,
                lv1CandidateCount: 0,
                lv1CandidatePreviousLv: '',
                lv1RearmRequested: true,
                lv1AcceptAfterAt: 0,
                pendingEvent: null
            };
        });
        const receiverOwners = new Map();
        targets.forEach((target, index) => {
            const receiverId = String(target && target.receiverId || '').trim();
            if (!target || !target.id || !receiverId) return;
            if (!receiverOwners.has(receiverId)) receiverOwners.set(receiverId, []);
            receiverOwners.get(receiverId).push(index);
        });
        const conflicts = [];
        for (const [receiverId, indexes] of receiverOwners.entries()) {
            if (indexes.length < 2) continue;
            const peer = workerById.get(receiverId);
            const peerNickname = normalizedOfficerNickname(peer && peer.nickname);
            const exactOwners = peerNickname
                ? indexes.filter((index) => normalizedOfficerNickname(targets[index].nickname) === peerNickname)
                : [];
            const keepIndex = exactOwners.length === 1 ? exactOwners[0] : -1;
            for (const index of indexes) {
                if (index === keepIndex) continue;
                targets[index] = {
                    ...targets[index],
                    receiverId: '',
                    receiverBindingManual: false,
                    lastLv: '',
                    lv1Latched: false,
                    lv1CandidateCount: 0,
                    lv1CandidatePreviousLv: '',
                    lv1RearmRequested: false,
                    lv1AcceptAfterAt: 0,
                    pendingEvent: null
                };
                changed = true;
            }
            conflicts.push(receiverId);
        }
        const usedReceiverIds = new Set(targets
            .map((target) => String(target && target.receiverId || '').trim())
            .filter(Boolean));
        targets.forEach((target, index) => {
            if (!target || !target.id || target.receiverId || target.receiverBindingManual === true) return;
            const friend = (friends || []).find((item) => officerFriendMatchesTarget(item, target));
            const nickname = normalizedOfficerNickname(friend && friend.nickname || target.nickname);
            const exactWorkers = nickname
                ? workers.filter((peer) => normalizedOfficerNickname(peer.nickname) === nickname)
                : [];
            const candidate = exactWorkers.length === 1 ? String(exactWorkers[0].accountId) : '';
            if (!candidate || usedReceiverIds.has(candidate)) return;
            targets[index] = {
                ...target,
                receiverId: candidate,
                receiverBindingManual: false,
                lastLv: '',
                lv1Latched: false,
                lv1CandidateCount: 0,
                lv1CandidatePreviousLv: '',
                lv1RearmRequested: true,
                lv1AcceptAfterAt: 0,
                pendingEvent: null
            };
            usedReceiverIds.add(candidate);
            changed = true;
        });
        return { targets, changed, conflicts };
    }

    function officerLayaStage() {
        try {
            const runtime = officerRuntime();
            return runtime && runtime.stage
                || pageWindow && pageWindow.Laya && pageWindow.Laya.stage
                || window.Laya && window.Laya.stage
                || null;
        } catch (_) {
            return null;
        }
    }

    function officerLayaChildren(node) {
        const result = [];
        const count = Number(node && node.numChildren) || 0;
        for (let index = 0; index < count; index += 1) {
            try {
                const child = node.getChildAt(index);
                if (child) result.push(child);
            } catch (_) {}
        }
        if (!result.length) {
            const children = node && (node._children || node._childs || node.children);
            if (Array.isArray(children)) result.push(...children.filter(Boolean));
        }
        return result;
    }

    function findOfficerFriendsView() {
        const runtime = officerRuntime();
        if (runtime && typeof runtime.win === 'function') {
            for (const name of ['FriendWindow', 'FriendsWindow', 'FriendListWindow', 'SocialWindow']) {
                try {
                    const win = runtime.win(name);
                    if (win && Array.isArray(win.goodFriendsList)) return win;
                } catch (_) {}
            }
        }
        const stage = officerLayaStage();
        if (!stage) return null;
        const queue = [stage];
        const seen = new WeakSet();
        let visited = 0;
        while (queue.length && visited < 6000) {
            const node = queue.shift();
            if (!node || typeof node !== 'object' || seen.has(node)) continue;
            seen.add(node);
            visited += 1;
            if (Array.isArray(node.goodFriendsList)) return node;
            queue.push(...officerLayaChildren(node));
        }
        return null;
    }

    

    function officerFriendManager() {
        const manager = officerGameClass('FriendManager');
        return manager && (typeof manager === 'object' || typeof manager === 'function') ? manager : null;
    }

    function officerUserDataByNickname(nickname) {
        const userDataClass = officerGameClass('UserData');
        if (!userDataClass || typeof userDataClass.GetNameInstance !== 'function') return null;
        try {
            return userDataClass.GetNameInstance(String(nickname || '').trim()) || null;
        } catch (_) {
            return null;
        }
    }

    function officerFriendSourceItems() {
        const manager = officerFriendManager();
        if (manager && typeof manager.GetGoodFriendsList === 'function') {
            try {
                const friends = manager.GetGoodFriendsList();
                if (Array.isArray(friends) && friends.length) return friends;
            } catch (_) {}
        }
        const view = findOfficerFriendsView();
        return view && Array.isArray(view.goodFriendsList) ? view.goodFriendsList : [];
    }

    function rememberOfficerFriendAccountIds(items) {
        if (!Array.isArray(items)) return;
        for (const item of items) {
            const data = item && (item.data || item.dataSource || item);
            const userData = item && item.userData;
            const nickname = String(data && (
                data.friendNickname ?? data.FriendNickname ?? data.nickname ?? data.Nickname
            ) || userData && (userData.nickname ?? userData.Nickname) || '').trim();
            const nicknameKey = normalizedOfficerNickname(nickname);
            const accountId = String(userData && (
                userData.clientId ?? userData.clientID ?? userData.ClientId ?? userData.ClientID
                ?? userData.accountId ?? userData.accountID ?? userData.userId ?? userData.userID ?? userData.uid
            ) || '').trim();
            if (nicknameKey && isOfficerAccountId(accountId)) {
                officerFriendAccountIdMap.set(nicknameKey, accountId);
            }
        }
    }

    async function scanAllOfficerFriendAccountIds(items) {
        // 保留离线好友已解析出的真实 ID；新资料按昵称更新，不能用会碰撞的一字节 friendID 做键。
        rememberOfficerFriendAccountIds(items);
        // FriendManager.GetGoodFriendsList is the authoritative complete relationship
        // list. The window-rendered rows remain only as a compatibility fallback.
    }

    function normalizeOfficerFriend(item) {
        const data = item && (item.data || item.dataSource || item);
        const rowUserData = item && item.userData;
        if (!data && !rowUserData) return null;
        const read = (keys, sources) => {
            for (const source of sources) {
                if (!source || typeof source !== 'object') continue;
                for (const key of keys) {
                    const value = source[key];
                    if (value !== undefined && value !== null && String(value).trim()) return String(value).trim();
                }
            }
            return '';
        };
        const rowNickname = read(
            ['friendNickname', 'FriendNickname', 'nickname', 'Nickname', 'Name', 'name'],
            [data, rowUserData, item]
        );
        const userData = officerUserDataByNickname(rowNickname) || rowUserData;
        const directAccountId = read(
            ['clientId', 'clientID', 'ClientId', 'ClientID', 'accountId', 'accountID', 'userId', 'userID', 'UserId', 'UserID', 'uid'],
            [userData, data, item]
        );
        const nickname = read(['friendNickname', 'FriendNickname', 'nickname', 'Nickname', 'Name', 'name'], [data, userData, item]);
        const nicknameKey = normalizedOfficerNickname(nickname);
        const legacyFriendId = read(['friendID', 'FriendID', 'friendId'], [data, userData, item]);
        if (nicknameKey && isOfficerAccountId(directAccountId)) {
            officerFriendAccountIdMap.set(nicknameKey, directAccountId);
        }
        const actualAccountId = isOfficerAccountId(directAccountId)
            ? directAccountId
            : (officerFriendAccountIdMap.get(nicknameKey) || '');
        return {
            friendId: actualAccountId,
            legacyFriendId,
            nickname,
            officerLv: read(['OfficerLevel', 'officerLevel', 'OfficerLv', 'officerLv'], [userData, data, item])
        };
    }

    function migrateOfficerListenerTargets(tab, friends) {
        let changed = false;
        const targets = tab.listenerTargets.map((target) => {
            const savedId = String(target && target.id || '').trim();
            if (!savedId) return target;
            let replacement = friends.find((friend) => officerFriendMatchesTarget(friend, target));
            if (!replacement && !target.nickname) {
                const legacyMatches = friends.filter((friend) => String(friend.legacyFriendId || '') === savedId);
                if (legacyMatches.length === 1) replacement = legacyMatches[0];
            }
            if (!replacement) return target;
            const stableId = officerFriendStableKey(replacement);
            if (!stableId) return target;
            const receiverId = target.receiverId
                || (isOfficerAccountId(savedId) && savedId !== replacement.friendId ? savedId : '');
            if (savedId === stableId
                && target.legacyFriendId === replacement.legacyFriendId
                && target.nickname === replacement.nickname
                && target.receiverId === receiverId) return target;
            changed = true;
            return {
                ...target,
                id: stableId,
                legacyFriendId: replacement.legacyFriendId,
                nickname: replacement.nickname,
                receiverId
            };
        });
        return { changed, targets };
    }

    function collectOfficerFriends() {
        const sourceItems = officerFriendSourceItems();
        if (!sourceItems.length) return [];
        rememberOfficerFriendAccountIds(sourceItems);
        const result = [];
        const ids = new Set();
        for (const item of sourceItems) {
            const friend = normalizeOfficerFriend(item);
            const stableId = officerFriendStableKey(friend);
            if (!friend || !stableId || ids.has(stableId)) continue;
            ids.add(stableId);
            result.push(friend);
        }
        return result;
    }

    function refreshSelectedOfficerFriendsFromServer(tab, friends, force = false) {
        const now = Date.now();
        const manager = officerFriendManager();
        const userDataClass = officerGameClass('UserData');
        const canRequestState = manager && typeof manager.LookFriendGameStateInfo === 'function';
        const canRequestBase = userDataClass && typeof userDataClass.SendUserBaseInfo === 'function';
        const canRequestDetail = userDataClass && typeof userDataClass.SendUserDetailReq === 'function';
        if (!canRequestState && !canRequestBase && !canRequestDetail) {
            officerFriendLastServerRefreshError = '游戏好友资料请求接口尚未就绪';
            return { requested: 0, error: officerFriendLastServerRefreshError };
        }
        const baseDue = canRequestBase
            && (force || now - officerFriendLastBaseRefreshAt >= OFFICER_FRIEND_BASE_REFRESH_MS);
        const detailDue = canRequestDetail
            && (force || now - officerFriendLastDetailRefreshAt >= OFFICER_FRIEND_DETAIL_REFRESH_MS);
        const stateDue = canRequestState
            && (force || now - officerFriendLastStateRefreshAt >= OFFICER_FRIEND_STATE_REFRESH_MS);
        if (!baseDue && !detailDue && !stateDue) {
            return { requested: 0, error: officerFriendLastServerRefreshError, skipped: true };
        }
        if (baseDue) officerFriendLastBaseRefreshAt = now;
        if (detailDue) officerFriendLastDetailRefreshAt = now;
        if (stateDue) officerFriendLastStateRefreshAt = now;
        officerFriendLastServerRefreshError = '';
        const selected = (tab.listenerTargets || []).filter((target) => target && target.id);
        const nicknames = new Set();
        for (const target of selected) {
            const friend = (friends || []).find((item) => officerFriendMatchesTarget(item, target));
            const nickname = String(friend && friend.nickname || target.nickname || '').trim();
            if (nickname) nicknames.add(nickname);
        }
        let requested = 0;
        const errors = [];
        for (const nickname of nicknames) {
            let sent = false;
            if (baseDue) {
                try {
                    userDataClass.SendUserBaseInfo(nickname, 0, false);
                    sent = true;
                } catch (error) {
                    errors.push('基础资料:' + (error && error.message || error));
                }
            }
            if (detailDue) {
                try {
                    // true bypasses UserData's 180-second UI tooltip cache. This is the
                    // same read-only detail request used by the official friend hover UI.
                    userDataClass.SendUserDetailReq(nickname, true);
                    sent = true;
                } catch (error) {
                    errors.push('详情:' + (error && error.message || error));
                }
            }
            if (stateDue) {
                try {
                    // FriendManager keeps its own five-second safety cooldown.
                    manager.LookFriendGameStateInfo(nickname);
                    sent = true;
                } catch (error) {
                    errors.push('状态:' + (error && error.message || error));
                }
            }
            if (sent) requested += 1;
        }
        officerFriendLastServerRefreshError = errors.join('；');
        return { requested, error: officerFriendLastServerRefreshError };
    }

    function officerBeijingTime() {
        return new Intl.DateTimeFormat('zh-CN', {
            timeZone: 'Asia/Shanghai',
            year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit',
            hour12: false
        }).format(new Date());
    }

    function makeOfficerLv1Event(target, previousLv, friend, tab) {
        const receiverId = resolveOfficerTargetReceiverId(friend, target, tab);
        if (!receiverId) return null;
        return {
            eventId: 'mail-officer-link:' + receiverId + ':' + Date.now() + ':' + Math.random().toString(36).slice(2, 10),
            targetId: receiverId,
            sourceId: officerOwnAccountId() || readOfficerLinkTab().ownAccountId || '',
            watchedFriendId: String(target && target.id || ''),
            watchedNickname: String(friend && friend.nickname || ''),
            previousOfficerLv: String(previousLv || ''),
            currentOfficerLv: '1',
            detectedAt: officerBeijingTime(),
            publishedAt: Date.now()
        };
    }

    async function publishOfficerPendingEvents() {
        if (officerLinkObserverBusy) return;
        const tab = readOfficerLinkTab();
        if (tab.mode !== 'listener' || !tab.active) return;
        const pendingEvents = tab.listenerTargets
            .filter((target) => target && target.pendingEvent)
            .map((target) => ({
                event: { ...target.pendingEvent },
                targetName: String(target.nickname || target.id || '')
            }));
        if (!pendingEvents.length) return;
        officerLinkObserverBusy = true;
        const sent = [];
        const failed = [];
        try {
            // 每个目标独立发送；单个目标失败不会阻塞或清除其他目标的事件。
            for (const pending of pendingEvents) {
                try {
                    const result = await officerLinkBridgeRequest('POST', '/event/publish', pending.event);
                    const latest = readOfficerLinkTab();
                    let cleared = false;
                    const targets = latest.listenerTargets.map((item) => {
                        const currentEventId = String(item && item.pendingEvent && item.pendingEvent.eventId || '');
                        if (!currentEventId || currentEventId !== String(pending.event.eventId || '')) return item;
                        cleared = true;
                        return {
                            ...item,
                            pendingEvent: null,
                            lv1Latched: true,
                            lv1CandidateCount: 0,
                            lv1CandidatePreviousLv: item.lv1CandidatePreviousLv
                                || (item.lastLv && item.lastLv !== '1' ? item.lastLv : ''),
                            lv1AcceptAfterAt: Math.max(
                                Number(item.lv1AcceptAfterAt) || 0,
                                Date.now() + OFFICER_POST_RUN_LV1_GUARD_MS
                            )
                        };
                    });
                    if (cleared) writeOfficerLinkTab({ ...latest, listenerTargets: targets });
                    sent.push((pending.targetName || pending.event.targetId)
                        + (result.duplicate ? '（桥中已存在）' : ''));
                } catch (error) {
                    failed.push((pending.targetName || pending.event.targetId) + '：'
                        + String(error && error.message || error));
                }
            }
            const statusParts = [];
            if (sent.length) statusParts.push('已分别发送 ' + sent.join('、'));
            if (failed.length) statusParts.push('发送失败并保留重试 ' + failed.join('；'));
            setOfficerLinkStatus(statusParts.join('；'), {
                bridgeOnline: sent.length > 0 || readOfficerLinkTab().bridgeOnline,
                lastError: failed.join('；')
            });
        } finally {
            officerLinkObserverBusy = false;
        }
    }

    async function officerListenerTick() {
        if (officerFriendFullScanBusy) return;
        let tab = readOfficerLinkTab();
        if (tab.mode !== 'listener' || !tab.active) return;
        if (Date.now() - officerLinkLastScanAt < OFFICER_LINK_SCAN_MS) return;
        officerLinkLastScanAt = Date.now();
        if (!officerLayaStage()) {
            setOfficerLinkStatus('监听端等待游戏运行环境；请保持监听账号在线');
            return;
        }
        const scanned = collectOfficerFriends();
        const migration = migrateOfficerListenerTargets(tab, scanned);
        if (migration.changed) {
            tab = { ...tab, listenerTargets: migration.targets };
            writeOfficerLinkTab(tab);
        }
        const selected = tab.listenerTargets.filter((target) => target.id);
        if (!selected.length) {
            setOfficerLinkStatus('请从好友列表中选择至少一个监听目标', {
                friends: scanned.length ? scanned : tab.friends
            });
            return;
        }
        const serverRefresh = refreshSelectedOfficerFriendsFromServer(
            tab,
            scanned.length ? scanned : tab.friends
        );
        if (!scanned.length) {
            setOfficerLinkStatus(serverRefresh.error
                ? ('主动刷新好友官阶失败：' + serverRefresh.error)
                : '已启动服务器主动刷新；等待首批好友官阶数据');
            return;
        }
        const friends = scanned;
        const bindingSync = synchronizeOfficerTargetReceiverBindings(tab, friends);
        if (bindingSync.changed) {
            tab = { ...tab, listenerTargets: bindingSync.targets };
            writeOfficerLinkTab(tab);
        }
        const statusParts = [];
        if (bindingSync.conflicts.length) statusParts.push('已阻止重复接收端绑定 ' + bindingSync.conflicts.join('、'));
        const refreshStatus = serverRefresh.error
            ? ('主动刷新异常：' + serverRefresh.error)
            : '服务器官阶基础资料每秒主动刷新（约1–2秒内更新）';
        let changed = scanned.length > 0;
        const targets = tab.listenerTargets.map((target) => {
            if (!target.id) return target;
            const friend = friends.find((item) => officerFriendMatchesTarget(item, target));
            if (!friend) {
                statusParts.push('ID ' + target.id + ' 等待官阶数据');
                return target;
            }
            const liveWorker = resolveOfficerWorkerPeer(friend, target, tab);
            const liveWorkerLv = /^\d+$/.test(String(liveWorker && liveWorker.officerLv || '').trim())
                ? String(liveWorker.officerLv).trim()
                : '';
            const friendLv = /^\d+$/.test(String(friend.officerLv || '').trim())
                ? String(friend.officerLv).trim()
                : '';
            const currentLv = liveWorkerLv || friendLv;
            if (!currentLv) {
                statusParts.push((friend.nickname || target.id) + ' 等待官阶数据');
                return target;
            }
            const previousLv = String(target.lastLv || '');
            statusParts.push((friend.nickname || friend.friendId) + ' LV' + currentLv
                + (liveWorkerLv ? '（接收端实时）' : ''));
            if (currentLv !== '1') {
                if (target.lastLv !== currentLv || target.lv1Latched
                    || target.lv1CandidateCount || target.lv1RearmRequested) changed = true;
                const nextAcceptAfterAt = liveWorkerLv
                    ? Math.max(Number(target.lv1AcceptAfterAt) || 0, Date.now() + OFFICER_POST_RUN_LV1_GUARD_MS)
                    : 0;
                return {
                    ...target,
                    lastLv: currentLv,
                    lv1Latched: false,
                    lv1CandidateCount: 0,
                    lv1CandidatePreviousLv: '',
                    lv1RearmRequested: false,
                    lv1AcceptAfterAt: nextAcceptAfterAt
                };
            }
            if (target.pendingEvent) {
                if (!target.lv1Latched || target.lastLv !== '1') changed = true;
                return {
                    ...target,
                    lastLv: '1',
                    lv1Latched: true,
                    lv1CandidateCount: OFFICER_LV1_CONFIRM_SAMPLES,
                    lv1CandidatePreviousLv: target.lv1CandidatePreviousLv || previousLv
                };
            }
            // 迁移旧版本遗留的错误锁存状态，经过同一冷却后自动恢复连续确认。
            if (target.lv1Latched === true
                && !target.lv1AcceptAfterAt
                && Math.max(0, Number(target.lv1CandidateCount) || 0) >= OFFICER_LV1_CONFIRM_SAMPLES) {
                changed = true;
                return {
                    ...target,
                    lv1Latched: false,
                    lv1CandidateCount: 0,
                    lv1CandidatePreviousLv: '',
                    lv1RearmRequested: false,
                    lv1AcceptAfterAt: Date.now() + OFFICER_POST_RUN_LV1_GUARD_MS
                };
            }
            const lv1AcceptAfterAt = Math.max(0, Number(target.lv1AcceptAfterAt) || 0);
            if (lv1AcceptAfterAt > Date.now() && target.lv1RearmRequested !== true) {
                const seconds = Math.max(1, Math.ceil((lv1AcceptAfterAt - Date.now()) / 1000));
                statusParts.push((friend.nickname || friend.friendId)
                    + ' 已看到 LV1，等待好友资料去缓存 ' + seconds + ' 秒后再确认');
                return {
                    ...target,
                    lv1Latched: false,
                    lv1CandidateCount: 0,
                    lv1CandidatePreviousLv: previousLv && previousLv !== '1' ? previousLv : target.lv1CandidatePreviousLv,
                    lv1RearmRequested: false
                };
            }
            const rearmRequested = target.lv1RearmRequested === true;
            const candidatePreviousLv = String(target.lv1CandidatePreviousLv || '')
                || (previousLv && previousLv !== '1' ? previousLv : 'initial-lv1');
            let candidateCount = Math.max(0, Number(target.lv1CandidateCount) || 0);
            // 每一次 LV1 样本都正常推进 0/3→3/3；页面跳转留下 lastLv=1、count=0 时也能继续。
            if (candidatePreviousLv && candidateCount < OFFICER_LV1_CONFIRM_SAMPLES) {
                candidateCount = Math.min(OFFICER_LV1_CONFIRM_SAMPLES, candidateCount + 1);
            }
            const recoverableLatched = target.lv1Latched === true
                && !target.pendingEvent
                && candidateCount < OFFICER_LV1_CONFIRM_SAMPLES
                && lv1AcceptAfterAt <= Date.now();
            if (candidateCount < OFFICER_LV1_CONFIRM_SAMPLES) {
                statusParts.push((friend.nickname || friend.friendId) + ' LV1；连续确认 '
                    + candidateCount + '/' + OFFICER_LV1_CONFIRM_SAMPLES);
                return {
                    ...target,
                    lastLv: '1',
                    lv1Latched: false,
                    lv1CandidateCount: candidateCount,
                    lv1CandidatePreviousLv: candidatePreviousLv,
                    lv1RearmRequested: rearmRequested,
                    lv1AcceptAfterAt: 0
                };
            }
            if (!target.lv1Latched || recoverableLatched) {
                const pendingEvent = makeOfficerLv1Event(
                    target,
                    candidatePreviousLv === 'initial-lv1' ? '' : candidatePreviousLv,
                    friend,
                    tab
                );
                if (!pendingEvent) {
                    statusParts.push((friend.nickname || friend.friendId) + (target.receiverId
                        ? (' LV1；等待接收端 ID ' + target.receiverId + ' 在线')
                        : ' LV1；未绑定接收端 ID（请填写该行）'));
                    return {
                        ...target,
                        lastLv: '1',
                        lv1Latched: false,
                        lv1CandidateCount: candidateCount,
                        lv1CandidatePreviousLv: candidatePreviousLv,
                        lv1RearmRequested: rearmRequested,
                        lv1AcceptAfterAt: 0,
                        pendingEvent: null
                    };
                }
                changed = true;
                return {
                    ...target,
                    lastLv: '1',
                    lv1Latched: true,
                    lv1CandidateCount: candidateCount,
                    lv1CandidatePreviousLv: candidatePreviousLv,
                    lv1RearmRequested: false,
                    lv1AcceptAfterAt: 0,
                    pendingEvent
                };
            }
            if (target.lastLv !== '1') changed = true;
            return {
                ...target,
                lastLv: '1',
                lv1CandidateCount: candidateCount,
                lv1CandidatePreviousLv: candidatePreviousLv,
                lv1RearmRequested: false,
                lv1AcceptAfterAt: 0
            };
        });
        if (changed) {
            writeOfficerLinkTab({
                ...tab,
                friends: scanned,
                listenerTargets: targets,
                status: statusParts.join('；') + '；' + refreshStatus
            });
        } else if (statusParts.length) {
            setOfficerLinkStatus(statusParts.join('；') + '；' + refreshStatus);
        } else {
            setOfficerLinkStatus('尚未找到好友官阶数据；请在游戏中打开一次好友列表');
        }
        // 发布前先将本次最新官阶写入监听端心跳；接收端会据此二次确认仍为 LV1。
        await officerHeartbeatTick(true);
        if (targets.some((target) => target.pendingEvent)) await publishOfficerPendingEvents();
    }

    function officerModeCycleIsRunning() {
        const state = readState();
        return state.enabled && !['idle', 'stopped'].includes(state.phase);
    }

    function officerReceiverIsPrimary(tab = readOfficerLinkTab()) {
        const receiverId = String(tab.receiverId || '').trim();
        if (!receiverId) return true;
        const sameAccountWorkers = (tab.bridgePeers || []).filter((peer) =>
            peer && peer.role === 'worker'
            && peer.knownBinding !== true
            && String(peer.accountId || '').trim() === receiverId
            && String(peer.peerId || '').trim());
        if (sameAccountWorkers.length < 2) return true;
        const primaryPeerId = sameAccountWorkers.map((peer) => String(peer.peerId)).sort()[0];
        return primaryPeerId === OFFICER_LINK_PEER_ID;
    }

    function officerListenerReportedLevel(tab, event) {
        const watchedFriendId = String(event && event.watchedFriendId || '').trim();
        const watchedNickname = normalizedOfficerNickname(event && event.watchedNickname);
        const listeners = (tab.bridgePeers || [])
            .filter((peer) => peer && peer.role === 'listener')
            .sort((left, right) => Number(right.lastSeenAt || 0) - Number(left.lastSeenAt || 0));
        for (const peer of listeners) {
            let report = null;
            try { report = JSON.parse(String(peer.targetId || '')); } catch (_) { continue; }
            const states = report && report.version === 1 && Array.isArray(report.watchedStates)
                ? report.watchedStates
                : [];
            const matched = states.find((item) => {
                const itemId = String(item && item.id || '').trim();
                const itemNickname = normalizedOfficerNickname(item && item.nickname);
                return (watchedFriendId && itemId === watchedFriendId)
                    || (watchedNickname && itemNickname === watchedNickname);
            });
            if (matched) return String(matched.officerLv || '').trim();
        }
        return '';
    }

    function startOfficerTriggeredCycle(event) {
        const tab = readOfficerLinkTab();
        if (tab.mode !== 'receiver' || !tab.active) return false;
        clearScheduledLoginTimer();
        const now = Date.now();
        writeState({
            enabled: true,
            phase: 'idle',
            targetLoginAt: now,
            plannedLoginDispatchAt: now,
            nextRunAt: now,
            triggerSource: 'officer-lv1',
            triggerEventId: String(event && event.eventId || ''),
            officerEventLoginRetryCount: Math.max(0, Number(event && event.loginRetryCount) || 0)
        }, { allowRecoveryTransition: true });
        startCycle({ forceLogin: true, claimMode: 'all' });
        return true;
    }

    async function acknowledgeOfficerEvent() {
        if (officerLinkBridgeBusy) return false;
        const tab = readOfficerLinkTab();
        const event = tab.activeEvent;
        if (tab.mode !== 'receiver' || !event || event.completed !== true) return false;
        officerLinkBridgeBusy = true;
        try {
            await officerLinkBridgeRequest('POST', '/event/ack', {
                eventId: String(event.eventId || ''),
                targetId: String(tab.receiverId || ''),
                consumerId: officerStableConsumerId(tab),
                completion: {
                    completedAt: Date.now(),
                    cycleId: String(event.cycleId || ''),
                    result: String(event.result || 'complete')
                }
            });
            setOfficerLinkStatus('本次 LV1 触发轮已确认完成，继续等待下一次 LV1', {
                activeEvent: null,
                bridgeOnline: true,
                lastError: ''
            });
            return true;
        } catch (error) {
            setOfficerLinkStatus('本轮已结束，但事件确认暂时失败，正在重试：' + (error && error.message || error), {
                bridgeOnline: false,
                lastError: String(error && error.message || error)
            });
            return false;
        } finally {
            officerLinkBridgeBusy = false;
        }
    }

    async function officerReceiverTick() {
        const tab = readOfficerLinkTab();
        if (tab.mode !== 'receiver' || !tab.active || !tab.receiverId) return;
        if (tab.activeEvent) {
            if (tab.activeEvent.awaitingLv1Validation === true) {
                const reportedLv = officerListenerReportedLevel(tab, tab.activeEvent);
                if (reportedLv === '1') {
                    const validatedEvent = {
                        ...tab.activeEvent,
                        awaitingLv1Validation: false,
                        validationDeadlineAt: 0,
                        validatedAt: Date.now()
                    };
                    patchOfficerLinkTab({
                        activeEvent: validatedEvent,
                        status: '监听端已再次确认目标仍为 LV1，正在启动领取'
                    });
                    startOfficerTriggeredCycle(validatedEvent);
                } else if (reportedLv && reportedLv !== '1') {
                    patchOfficerLinkTab({
                        activeEvent: {
                            ...tab.activeEvent,
                            awaitingLv1Validation: false,
                            completed: true,
                            result: 'level-changed-before-start',
                            completedAt: Date.now()
                        },
                        status: '事件已取消：监听端当前报告目标为 LV' + reportedLv + '，不允许启动登录'
                    });
                } else if (Date.now() >= Number(tab.activeEvent.validationDeadlineAt || 0)) {
                    patchOfficerLinkTab({
                        activeEvent: {
                            ...tab.activeEvent,
                            awaitingLv1Validation: false,
                            completed: true,
                            result: 'lv1-validation-timeout',
                            completedAt: Date.now()
                        },
                        status: '事件已取消：4.5秒内未取得监听端的实时 LV1 二次确认'
                    });
                }
                return;
            }
            if (tab.activeEvent.completed === true
                && Date.now() - officerLinkLastBridgePollAt >= OFFICER_LINK_BRIDGE_POLL_MS) {
                officerLinkLastBridgePollAt = Date.now();
                await acknowledgeOfficerEvent();
            } else if (tab.activeEvent.completed !== true && officerModeCycleIsRunning()) {
                if (tab.activeEvent.orphanDetectedAt) {
                    patchOfficerLinkTab({ activeEvent: { ...tab.activeEvent, orphanDetectedAt: 0 } });
                }
            } else if (tab.activeEvent.completed !== true) {
                const retryAt = Math.max(0, Number(tab.activeEvent.nextRetryAt) || 0);
                if (retryAt > 0 && Date.now() >= retryAt) {
                    const retryEvent = { ...tab.activeEvent, nextRetryAt: 0 };
                    patchOfficerLinkTab({
                        activeEvent: retryEvent,
                        status: '登录恢复等待结束，正在重试本次 LV1 触发轮'
                    });
                    startOfficerTriggeredCycle(retryEvent);
                } else if (retryAt <= 0) {
                    const dormantSince = Math.max(
                        0,
                        Number(tab.activeEvent.orphanDetectedAt) || Number(tab.activeEvent.claimedAt) || 0
                    );
                    if (!tab.activeEvent.orphanDetectedAt) {
                        patchOfficerLinkTab({
                            activeEvent: { ...tab.activeEvent, orphanDetectedAt: Date.now() },
                            status: '检测到已领取事件没有运行任务；正在确认页面状态，8秒后自动恢复'
                        });
                    } else if (Date.now() - dormantSince >= OFFICER_EVENT_ORPHAN_RESTART_MS) {
                        const recoveryEvent = {
                            ...tab.activeEvent,
                            orphanDetectedAt: 0,
                            orphanRestartCount: Math.max(0, Number(tab.activeEvent.orphanRestartCount) || 0) + 1
                        };
                        patchOfficerLinkTab({
                            activeEvent: recoveryEvent,
                            status: '已恢复被页面跳转中断的 LV1 事件，正在重新执行'
                        });
                        startOfficerTriggeredCycle(recoveryEvent);
                    }
                }
            }
            return;
        }
        if (officerModeCycleIsRunning()) return;
        if (!officerReceiverIsPrimary(tab)) {
            setOfficerLinkStatus('检测到同一接收端 ID 存在多个在线页面；本页面处于备用状态，由主页面领取事件', {
                bridgeOnline: true,
                lastError: ''
            });
            return;
        }
        if (Date.now() - officerLinkLastBridgePollAt < OFFICER_LINK_BRIDGE_POLL_MS || officerLinkBridgeBusy) return;
        officerLinkLastBridgePollAt = Date.now();
        officerLinkBridgeBusy = true;
        try {
            const result = await officerLinkBridgeRequest('POST', '/event/claim', {
                targetId: tab.receiverId,
                consumerId: officerStableConsumerId(tab)
            });
            if (result.event) {
                const event = { ...result.event, completed: false, claimedAt: Date.now() };
                const publishedAt = Math.max(0, Number(event.publishedAt) || 0);
                const eventAgeMs = publishedAt ? Math.max(0, Date.now() - publishedAt) : 0;
                if (!publishedAt || eventAgeMs > OFFICER_EVENT_MAX_START_AGE_MS) {
                    setOfficerLinkStatus(
                        '已丢弃过期 LV1 事件（延迟 ' + formatDuration(eventAgeMs)
                            + '）；不会在当前官阶未知或已变化时启动登录',
                        {
                            activeEvent: {
                                ...event,
                                completed: true,
                                result: 'stale-event',
                                completedAt: Date.now()
                            },
                            bridgeOnline: true,
                            lastError: ''
                        }
                    );
                    return;
                }
                const reportedLv = officerListenerReportedLevel(readOfficerLinkTab(), event);
                if (reportedLv !== '1') {
                    setOfficerLinkStatus(
                        reportedLv
                            ? ('已领取事件，但监听端当前报告目标为 LV' + reportedLv + '；等待确认后取消')
                            : '已领取事件；正在等待监听端实时确认目标仍为 LV1',
                        {
                            activeEvent: {
                                ...event,
                                awaitingLv1Validation: true,
                                validationDeadlineAt: Date.now() + OFFICER_LV1_VALIDATION_TIMEOUT_MS
                            },
                            bridgeOnline: true,
                            lastError: ''
                        }
                    );
                    return;
                }
                event.validatedAt = Date.now();
                setOfficerLinkStatus(
                    '收到 ID ' + tab.receiverId + ' 的 LV1 事件，现由邮件助手执行完整一轮',
                    { activeEvent: event, bridgeOnline: true, lastError: '' }
                );
                startOfficerTriggeredCycle(event);
            } else {
                setOfficerLinkStatus('本地桥已连接；等待 ID ' + tab.receiverId + ' 的下一次 LV1 事件', {
                    bridgeOnline: true,
                    lastError: ''
                });
            }
        } catch (error) {
            setOfficerLinkStatus('等待官阶事件：' + (error && error.message || error), {
                bridgeOnline: false,
                lastError: String(error && error.message || error)
            });
        } finally {
            officerLinkBridgeBusy = false;
        }
    }

    async function officerHeartbeatTick(force = false) {
        const tab = readOfficerLinkTab();
        if (!tab.active || !['listener', 'receiver'].includes(tab.mode)) return;
        if ((!force && Date.now() - officerLinkLastHeartbeatAt < OFFICER_LINK_HEARTBEAT_MS) || officerLinkBridgeBusy) return;
        officerLinkLastHeartbeatAt = Date.now();
        const ownId = officerOwnAccountId() || tab.ownAccountId || '';
        const ownNickname = officerOwnNickname() || tab.ownNickname || '';
        const watchedStates = tab.mode === 'listener'
            ? tab.listenerTargets
                .filter((target) => target && target.id)
                .map((target) => {
                    const friend = (tab.friends || []).find((item) => officerFriendMatchesTarget(item, target));
                    return {
                        id: String(target.id || ''),
                        nickname: String(friend && friend.nickname || target.nickname || ''),
                        officerLv: String(target.lastLv || friend && friend.officerLv || '')
                    };
                })
            : [];
        const targetId = tab.mode === 'receiver'
            ? tab.receiverId
            : JSON.stringify({ version: 1, watchedStates });
        try {
            const result = await officerLinkBridgeRequest('POST', '/peer/heartbeat', {
                peerId: OFFICER_LINK_PEER_ID,
                role: tab.mode === 'listener' ? 'listener' : 'worker',
                accountId: ownId,
                nickname: ownNickname,
                officerLv: tab.mode === 'receiver' ? officerOwnLevel() : '',
                targetId,
                watchedStates,
                page: location.href
            });
            const livePeers = Array.isArray(result.peers) ? result.peers : [];
            const bridgePeers = tab.mode === 'listener'
                ? mergeOfficerKnownWorkerBindings(livePeers, result.knownWorkerBindings)
                : livePeers;
            patchOfficerLinkTab({
                ownAccountId: ownId,
                ownNickname,
                bridgeOnline: true,
                bridgePeers,
                lastError: ''
            });
        } catch (error) {
            patchOfficerLinkTab({
                bridgeOnline: false,
                lastError: String(error && error.message || error)
            });
        }
    }

    async function officerLinkTick() {
        if (officerLinkTickBusy) return;
        officerLinkTickBusy = true;
        try {
        const tab = readOfficerLinkTab();
        const detectedId = officerOwnAccountId();
        const detectedNickname = officerOwnNickname();
        if ((detectedId && detectedId !== tab.ownAccountId)
            || (detectedNickname && detectedNickname !== tab.ownNickname)) {
            patchOfficerLinkTab({
                ownAccountId: detectedId || tab.ownAccountId,
                ownNickname: detectedNickname || tab.ownNickname,
                receiverId: tab.mode === 'receiver' && !tab.receiverId ? detectedId : tab.receiverId
            });
        }
        // 先拿到在线页面名单，再进行同一接收 ID 的主实例选举。
        await officerHeartbeatTick();
        if (tab.mode === 'listener') await officerListenerTick();
        if (tab.mode === 'receiver') await officerReceiverTick();
        } finally {
            officerLinkTickBusy = false;
        }
    }

    function updateOfficerLinkMode(mode) {
        const nextMode = ['timer', 'listener', 'receiver'].includes(mode) ? mode : 'timer';
        const current = readOfficerLinkTab();
        const ownId = officerOwnAccountId() || current.ownAccountId || '';
        writeOfficerLinkTab({
            ...current,
            mode: nextMode,
            active: false,
            ownAccountId: ownId,
            receiverId: nextMode === 'receiver' && !current.receiverId ? ownId : current.receiverId,
            activeEvent: null,
            status: nextMode === 'timer'
                ? '已切换为倒计时启动；原周期设置保持不变，点击“启动”后生效'
                : (nextMode === 'listener'
                    ? '已切换为监听端；选择最多三个好友后点击“启动监听”'
                    : '已切换为接收端；确认本账号游戏 ID 后点击“启用等待”')
        });
        clearScheduledLoginTimer();
        const state = readState();
        if (!state.enabled || ['idle', 'stopped'].includes(state.phase)) {
            writeState({
                enabled: false,
                phase: 'stopped',
                nextRunAt: 0,
                targetLoginAt: 0,
                plannedLoginDispatchAt: 0,
                triggerSource: '',
                triggerEventId: ''
            }, { allowRecoveryTransition: true });
        } else {
            setOfficerLinkStatus('启动方式已切换；当前正在执行的一轮完成后按新方式等待');
        }
    }

    

    async function refreshOfficerFriends() {
        if (officerFriendFullScanBusy) return;
        const sourceItems = officerFriendSourceItems();
        if (!sourceItems.length) {
            setOfficerLinkStatus('好友管理器尚未收到列表数据；请保持监听账号在线后重试');
            return;
        }
        officerFriendFullScanBusy = true;
        if (officerLinkRefreshFriendsButton) officerLinkRefreshFriendsButton.disabled = true;
        setOfficerLinkStatus('正在读取完整好友列表并解析真实账号 ID…');
        try {
            await scanAllOfficerFriendAccountIds(sourceItems);
            const scanned = collectOfficerFriends();
            const rawCount = sourceItems.length;
            const unresolvedCount = Math.max(0, rawCount - scanned.length);
            const tab = readOfficerLinkTab();
            const migration = migrateOfficerListenerTargets(tab, scanned);
            const bindingSync = synchronizeOfficerTargetReceiverBindings({
                ...tab,
                listenerTargets: migration.targets
            }, scanned);
            refreshSelectedOfficerFriendsFromServer({
                ...tab,
                listenerTargets: bindingSync.targets
            }, scanned, true);
            setOfficerLinkStatus(
                scanned.length
                    ? ('已读取 ' + scanned.length + ' 位有效好友'
                        + (unresolvedCount ? ('；另有 ' + unresolvedCount + ' 条历史记录无真实账号 ID') : '')
                        + '，可选择最多三个目标')
                    : '好友列表存在，但没有解析到可用于联动的真实账号 ID',
                {
                    friends: scanned.length ? scanned : tab.friends,
                    // 只合并好友资料与安全绑定，不重置目标自己的 LV1 运行状态。
                    listenerTargets: bindingSync.targets
                }
            );
        } catch (error) {
            setOfficerLinkStatus('完整好友列表读取失败：' + (error && error.message || error));
        } finally {
            officerFriendFullScanBusy = false;
            if (officerLinkRefreshFriendsButton) officerLinkRefreshFriendsButton.disabled = false;
        }
    }

    function updateOfficerListenerTarget(index, value) {
        const tab = readOfficerLinkTab();
        const id = String(value || '').trim();
        const currentTarget = tab.listenerTargets[index] || {};
        const friend = (tab.friends || []).find((item) => officerFriendStableKey(item) === id);
        const onlineWorkers = canonicalOfficerWorkerPeers(tab);
        const friendNickname = normalizedOfficerNickname(friend && friend.nickname);
        const exactWorker = id && onlineWorkers.find((peer) =>
            friendNickname && normalizedOfficerNickname(peer.nickname) === friendNickname);
        const sameTarget = id && String(currentTarget.id || '') === id;
        let receiverBindingManual = sameTarget && currentTarget.receiverBindingManual === true;
        let receiverId = receiverBindingManual
            ? String(currentTarget.receiverId || '')
            : (exactWorker ? String(exactWorker.accountId) : (sameTarget ? String(currentTarget.receiverId || '') : ''));
        const receiverIdConflict = receiverId && tab.listenerTargets.some((target, targetIndex) =>
            targetIndex !== index && target && target.id
            && String(target.receiverId || '').trim() === receiverId);
        if (receiverIdConflict) {
            receiverId = '';
            receiverBindingManual = false;
        }
        const targets = tab.listenerTargets.map((target, targetIndex) => targetIndex === index
            ? {
                id,
                legacyFriendId: String(friend && friend.legacyFriendId || ''),
                nickname: String(friend && friend.nickname || ''),
                receiverId,
                receiverBindingManual,
                lastLv: '',
                lv1Latched: false,
                lv1CandidateCount: 0,
                lv1CandidatePreviousLv: '',
                lv1RearmRequested: true,
                lv1AcceptAfterAt: 0,
                pendingEvent: null
            }
            : target);
        const duplicate = id && targets.some((target, targetIndex) => targetIndex !== index && target.id === id);
        if (duplicate) {
            setOfficerLinkStatus('同一个好友不能重复占用多个监听位置');
            return;
        }
        setOfficerLinkStatus(id
            ? ('监听位置 ' + (index + 1) + ' 已选择 ' + (friend && friend.nickname || id)
                + (receiverId
