    function buildOfflineLoginSchedule(anchorAt, intervalMs) {
        const anchor = Number(anchorAt) > 0 ? Number(anchorAt) : Date.now();
        const targetLoginAt = anchor + Math.max(0, Number(intervalMs) || 0);
        // Authenticate as soon as real logout is confirmed; wait only at the version page.
