    function setCycleMs(valueMs) {
        const cycleMs = normalizeCycleMs(valueMs);
        storageSet(CYCLE_SETTING_KEY, cycleMs);
        const state = readState();
        const waiting = state.enabled && Number(state.scheduledEntryAt) > Date.now();
        const patch = waiting ? { scheduledEntryAt: (Number(state.offlineScheduleAnchorAt) || Date.now()) + cycleMs,
            targetLoginAt: (Number(state.offlineScheduleAnchorAt) || Date.now()) + cycleMs } : {};
        if (state.phase === 'idle' && state.enabled) Object.assign(patch,
            buildOfflineLoginSchedule(Number(state.offlineScheduleAnchorAt) || Date.now(), cycleMs));
        clearScheduledLoginTimer();
        setMessage(`等待周期已设为 ${formatDuration(cycleMs)}${waiting ? '；本次进入时间已更新' : '；下次排程生效'}`, patch);
        return cycleMs;
