			setMessage("当前自动日常流程正在执行，请等待本轮结束");
			return;
		}
		const bridge = mailRuntimeServices();
		if (!bridge || typeof bridge.claimDailyRewards !== "function") {
			setMessage("独立执行接口尚未加载，请重启微端后重试");
			return;
		}
		const selection = standaloneRewardSelection(kind);
		if (kind === "generalUpgrade" && !Object.values(selection.generalUpgradeCounts).some((value) => value > 0)) {
			setMessage("武将升阶：请先设置至少一个目标人数");
			return;
		}
		generalUpgradeRunBusy = !0;
		if (generalUpgradeRunButton) generalUpgradeRunButton.disabled = !0;
		if (generalUpgradeTaskButton) generalUpgradeTaskButton.disabled = !0;
		if (generalUpgradeRunStatus) generalUpgradeRunStatus.textContent = kind === "generalUpgrade" ? "正在独立执行武将升阶…" : "正在独立执行官阶任务…";
		try {
			const result = await Promise.resolve(bridge.claimDailyRewards(selection));
			appendDailyRewardTrace(selection, result, null, null, "day");
			const text = kind === "generalUpgrade"
				? describeGeneralUpgradeReport(result && result.generalUpgrade)
				: describeStandaloneOfficerTasks(result && result.officerTasks);
			if (generalUpgradeRunStatus) generalUpgradeRunStatus.textContent = text;
			setMessage(text);
		} catch (error) {
			const text = `独立执行失败：${error instanceof Error ? error.message : String(error)}`;
			if (generalUpgradeRunStatus) generalUpgradeRunStatus.textContent = text;
			setMessage(text);
		} finally {
			generalUpgradeRunBusy = !1;
			if (generalUpgradeRunButton) generalUpgradeRunButton.disabled = !1;
			if (generalUpgradeTaskButton) generalUpgradeTaskButton.disabled = !1;
