    function normalizeDailyRewardItems(value, fallback) {
        const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
        const base = fallback && typeof fallback === 'object' ? fallback : legacyDailyRewardItems();
        const normalized = {};
        for (const item of DAILY_REWARD_ITEM_DEFS) {
            if (Object.prototype.hasOwnProperty.call(source, item.key)) {
                normalized[item.key] = source[item.key] === true;
                continue;
            }
            if (item.key === 'officerPromote') {
                const hasOldPromotionControl = Object.prototype.hasOwnProperty.call(source, 'officerSprint')
                    || Object.prototype.hasOwnProperty.call(source, 'officerTasks');
                normalized[item.key] = hasOldPromotionControl
                    ? source.officerSprint === true || source.officerTasks === true
                    : base.officerPromote === true;
                continue;
            }
            if (item.key === 'generalUpgrade') {
                // 新增的消耗型功能必须默认关闭，不能从任何旧官阶开关继承点亮状态。
                normalized[item.key] = false;
                continue;
            }
            if (item.key === 'officerSprint') {
                normalized[item.key] = Object.prototype.hasOwnProperty.call(source, 'officerRewards')
                    ? source.officerRewards === true
                    : (Object.prototype.hasOwnProperty.call(source, 'officerSprint') ? source.officerSprint === true : base.officerSprint === true);
                continue;
            }
            if (item.key === 'officerDailyWeekly') {
                if (Object.prototype.hasOwnProperty.call(source, 'officerRewards')) normalized[item.key] = source.officerRewards === true;
                else {
                    const oldRewardKeys = ['officerDay', 'officerWeek'];
                    const hasOldRewardControl = oldRewardKeys.some((key) => Object.prototype.hasOwnProperty.call(source, key));
                    normalized[item.key] = hasOldRewardControl
                        ? oldRewardKeys.some((key) => source[key] === true)
                        : base.officerDailyWeekly === true;
                }
                continue;
            }
            normalized[item.key] = DAILY_REWARD_SUPPORTED_ITEM_KEYS.has(item.key) && base[item.key] === true;
        }
        return normalized;
    }

    function readDailyRewardItems() {
        const stored = storageGet(DAILY_ITEMS_KEY, null);
        if (stored && typeof stored === 'object' && !Array.isArray(stored)) {
            const normalized = normalizeDailyRewardItems(stored);
            const changed = DAILY_REWARD_ITEM_DEFS.some((item) => (stored[item.key] === true) !== (normalized[item.key] === true))
                || Object.keys(stored).some((key) => !DAILY_REWARD_SUPPORTED_ITEM_KEYS.has(key));
            if (changed) storageSet(DAILY_ITEMS_KEY, normalized);
            return normalized;
        }
        const migrated = legacyDailyRewardItems();
        storageSet(DAILY_ITEMS_KEY, migrated);
        return migrated;
    }

