        const stored = storageGet(OFFICER_TARGET_LEVEL_KEY, null);
        let candidate = stored;
        if (candidate == null) {
            try {
                const legacy = localStorage.getItem('xc-h5-auto-officer-promoter-target-level-v1');
                if (Number(legacy) > 0) candidate = Number(legacy);
            } catch (_) {}
        }
        const normalized = normalizeOfficerTargetLevel(candidate == null ? OFFICER_TARGET_LEVEL_DEFAULT : candidate);
        if (stored == null || Number(stored) !== normalized) storageSet(OFFICER_TARGET_LEVEL_KEY, normalized);
        return normalized;
    }

    function setOfficerTargetLevel(value) {
        const officialMax = visibleOfficialOfficerMaxLevel();
        const normalized = normalizeOfficerTargetLevel(value, officialMax);
        storageSet(OFFICER_TARGET_LEVEL_KEY, normalized);
        storageSet(DAILY_LAST_KEY, '');
        setMessage(`官阶晋升目标：LV${normalized}（全服统一上限 LV${officialMax}）`);
        renderPanel();
        return normalized;
    }

    function dailyRewardBridgeSelection() {
        const items = readDailyRewardItems();
        const frequency = readDailyFreq();
        const dailyFrequencyDue = frequency === 'cycle' || storageGet(DAILY_LAST_KEY, '') !== todayStamp();
        const generalUpgradeAccountId = items.generalUpgrade === true ? currentGeneralUpgradeAccountId() : '';
        const generalUpgradeRoster = generalUpgradeAccountId ? readGeneralUpgradeRoster(generalUpgradeAccountId) : null;
        const recentTrace = readDailyRewardTrace();
        const previousOfficerTasks = [...recentTrace].reverse().find((entry) => entry?.officerTasks?.enabled === true)?.officerTasks || null;
        const previousOfficerTasksUnconfirmed = previousOfficerTasks && (
            String(previousOfficerTasks.status || '') === 'partial' ||
            Number(previousOfficerTasks.remainingCount || 0) > 0 ||
            Number(previousOfficerTasks.pendingPoint || 0) > 0
        );
        const selection = {
            ...items,
            officerTargetLevel: readOfficerTargetLevel(),
            officerTaskSendIntervalMs: previousOfficerTasksUnconfirmed
                ? OFFICER_TASK_SAFE_SEND_INTERVAL_MS
                : OFFICER_TASK_FAST_SEND_INTERVAL_MS,
            generalUpgradeCounts: readGeneralUpgradeCounts(),
            generalUpgradeAccountId,
            generalUpgradeRosterIds: generalUpgradeRoster?.ids || [],
            generalUpgradeRosterUpdatedAt: generalUpgradeRoster?.updatedAt || ''
        };
        if (!dailyFrequencyDue) {
            for (const item of DAILY_REWARD_ITEM_DEFS) {
                if (!DAILY_REWARD_FIXED_EACH_CYCLE_KEYS.has(item.key) && !['mailClaim', 'giftCodes', 'blackMagicOrb'].includes(item.key)) {
                    selection[item.key] = false;
                }
            }
        }
        return { items, selection, frequency, dailyFrequencyDue };
    }

    function readDailyFreq() {
        return storageGet(DAILY_FREQ_KEY, 'day') === 'cycle' ? 'cycle' : 'day';
    }

    function toggleDailyFreq() {
        const next = readDailyFreq() === 'day' ? 'cycle' : 'day';
        storageSet(DAILY_FREQ_KEY, next);
        storageSet(DAILY_LAST_KEY, '');
        setMessage(next === 'cycle'
            ? '日常奖励改为“每轮都领”（所有已点亮的非固定每轮项目都会执行）'
            : '日常奖励改为“每天一次”');
    }




    const DAILY_REWARD_TRACE_LABELS = Object.freeze({
        freeBless: Object.freeze(['免费祈福']),
			activityAll: Object.freeze(['军典档位一键', '军典档位']),
			newJd: Object.freeze(['节钺令']),
			officerPromote: Object.freeze(['官阶晋升']),
        officerTasks: Object.freeze(['官阶任务']),
        generalUpgrade: Object.freeze(['武将升阶']),
        officerSprint: Object.freeze(['官阶冲刺']),
        officerDailyWeekly: Object.freeze(['官阶日周', '官阶日奖', '官阶周奖'])
    });

    function compactDailyRewardStateSnapshot(snapshot) {
        if (!snapshot || typeof snapshot !== 'object') return null;
        const source = snapshot.officer && typeof snapshot.officer === 'object' ? snapshot.officer : {};
        const pick = (...keys) => {
            for (const key of keys) {
                const value = source[key];
                if (typeof value === 'number' || typeof value === 'string' || typeof value === 'boolean') return value;
            }
            return null;
        };
        const officer = {
            level: pick('OfficerSLv', 'OfficerLv', 'curOfficerLv'),
            maxLevel: pick('MaxOfficerLv', 'maxOfficerLv'),
            point: pick('OfficerPoint', 'officerPoint'),
            dayRewardTime: pick('DayRewardTime', 'dayRewardTime'),
            weekRewardTime: pick('WeekRewardTime', 'weekRewardTime')
        };
        return { officer };
    }

    function compactOfficerTaskReport(value) {
        if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
        return {
            enabled: value.enabled === true,
            status: String(value.status || 'unknown'),
            success: value.success === true,
            dataReady: value.dataReady === true,
            dataInited: value.dataInited === true ? true : value.dataInited === false ? false : null,
            taskMapReady: value.taskMapReady === true,
            readinessAttempts: Math.max(0, Number(value.readinessAttempts) || 0),
            readinessWaitedMs: Math.max(0, Number(value.readinessWaitedMs) || 0),
            initialCount: Math.max(0, Number(value.initialCount) || 0),
            requestCount: Math.max(0, Number(value.requestCount) || 0),
            sentCount: Math.max(0, Number(value.sentCount) || 0),
            confirmedCount: Math.max(0, Number(value.confirmedCount) || 0),
            remainingCount: Math.max(0, Number(value.remainingCount) || 0),
            requestedPoint: Math.max(0, Number(value.requestedPoint) || 0),
            confirmedPoint: Math.max(0, Number(value.confirmedPoint) || 0),
            pendingPoint: Math.max(0, Number(value.pendingPoint) || 0),
            sendIntervalMs: Math.max(0, Number(value.sendIntervalMs) || 0),
            elapsedMs: Math.max(0, Number(value.elapsedMs) || 0),
            error: String(value.error || '')
        };
    }

    function compactGeneralUpgradeReport(value) {
        if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
        const stages = Array.isArray(value.stages) ? value.stages.map((stage) => ({
            key: String(stage?.key || ''),
            from: Math.max(0, Number(stage?.from) || 0),
            to: Math.max(0, Number(stage?.to) || 0),
            targetCount: Math.max(0, Number(stage?.targetCount) || 0),
            candidateCount: Math.max(0, Number(stage?.candidateCount) || 0),
            sentCount: Math.max(0, Number(stage?.sentCount) || 0),
            confirmedCount: Math.max(0, Number(stage?.confirmedCount) || 0),
            alreadySatisfiedCount: Math.max(0, Number(stage?.alreadySatisfiedCount) || 0),
            transitionConfirmedCount: Math.max(0, Number(stage?.transitionConfirmedCount) || 0),
            confirmedIds: Array.isArray(stage?.confirmedIds)
                ? stage.confirmedIds.map((id) => Math.max(0, Number(id) || 0)).filter(Boolean).slice(0, 20)
                : [],
            blockedCount: Math.max(0, Number(stage?.blockedCount) || 0),
            missingCount: Math.max(0, Number(stage?.missingCount) || 0),
            unsentCount: Math.max(0, Number(stage?.unsentCount) || 0),
            unconfirmedCount: Math.max(0, Number(stage?.unconfirmedCount) || 0),
            materialPlanCount: Math.max(0, Number(stage?.materialPlanCount) || 0),
            materialFallbackCount: Math.max(0, Number(stage?.materialFallbackCount) || 0),
            materialUnavailableCount: Math.max(0, Number(stage?.materialUnavailableCount) || 0),
            materialPlans: Array.isArray(stage?.materialPlans) ? stage.materialPlans.map((item) => ({
                id: Math.max(0, Number(item?.id) || 0),
                goodId: Math.max(0, Number(item?.goodId) || 0),
                name: String(item?.name || ''),
                count: Math.max(0, Number(item?.count) || 0),
                fallback: item?.fallback === true
            })).filter((item) => item.id > 0).slice(0, 20) : [],
            blockedReason: String(stage?.blockedReason || '')
        })) : [];
        return {
            enabled: value.enabled === true,
            status: String(value.status || 'unknown'),
            success: value.success === true,
            reason: String(value.reason || ''),
            selectedCount: Math.max(0, Number(value.selectedCount) || 0),
            targetTotal: Math.max(0, Number(value.targetTotal) || 0),
            sentTotal: Math.max(0, Number(value.sentTotal) || 0),
            confirmedTotal: Math.max(0, Number(value.confirmedTotal) || 0),
            freshStateGuard: String(value.freshStateGuard || ''),
            execution: value.execution && typeof value.execution === 'object' ? {
                mode: String(value.execution.mode || ''),
                workerCount: Math.max(0, Number(value.execution.workerCount) || 0),
                maxActiveConfirmations: Math.max(0, Number(value.execution.maxActiveConfirmations) || 0),
                sendIntervalMs: Math.max(0, Number(value.execution.sendIntervalMs) || 0),
                minimumObservedSendGapMs: Math.max(0, Number(value.execution.minimumObservedSendGapMs) || 0),
				urgentContinuationCount: Math.max(0, Number(value.execution.urgentContinuationCount) || 0),
				singleConfirmTimeoutMs: Math.max(0, Number(value.execution.singleConfirmTimeoutMs) || 0),
				totalBudgetMs: Math.max(0, Number(value.execution.totalBudgetMs) || 0),
				eventMonitorInstalled: value.execution.eventMonitorInstalled === true,
				eventObservedSuccessCount: Math.max(0, Number(value.execution.eventObservedSuccessCount) || 0),
				lateConfirmedCount: Math.max(0, Number(value.execution.lateConfirmedCount) || 0),
				materialInventory: Array.isArray(value.execution.materialInventory)
					? value.execution.materialInventory.map((item) => ({
						goodId: Math.max(0, Number(item?.goodId) || 0),
						name: String(item?.name || ''),
						count: Math.max(0, Number(item?.count) || 0),
						exp: Math.max(0, Number(item?.exp) || 0)
					})).filter((item) => item.goodId > 0).slice(0, 8)
					: (value.execution.materialInventory && typeof value.execution.materialInventory === 'object'
						? { available: value.execution.materialInventory.available === true, reason: String(value.execution.materialInventory.reason || '') }
						: null),
				elapsedMs: Math.max(0, Number(value.execution.elapsedMs) || 0),
                apiDiagnostic: String(value.execution.apiDiagnostic || '').slice(0, 12000)
            } : null,
            preflight: value.preflight && typeof value.preflight === 'object' ? {
                ready: value.preflight.ready === true,
                status: String(value.preflight.status || ''),
                stable: value.preflight.stable === true,
                rosterCount: Math.max(0, Number(value.preflight.rosterCount ?? value.preflight.totalGenerals) || 0),
                checkedCount: Math.max(0, Number(value.preflight.checkedCount) || 0),
                sentinelId: Math.max(0, Number(value.preflight.sentinelId) || 0),
                sentinelStar: Math.max(0, Number(value.preflight.sentinelStar) || 0),
				upgradedCount: Math.max(0, Number(value.preflight.upgradedCount ?? value.preflight.twoStarCount) || 0),
				waitedMs: Math.max(0, Number(value.preflight.waitedMs) || 0),
				snapshot: value.preflight.snapshot && typeof value.preflight.snapshot === 'object' ? {
					rawCount: Math.max(0, Number(value.preflight.snapshot.rawCount) || 0),
					acceptedCount: Math.max(0, Number(value.preflight.snapshot.acceptedCount) || 0),
					rejectedCount: Math.max(0, Number(value.preflight.snapshot.rejectedCount) || 0)
				} : null
            } : null,
            stages
        };
    }

    function describeGeneralUpgradeReport(value) {
        const report = compactGeneralUpgradeReport(value);
        if (!report) return '失败：本轮无返回结果';
        const statusText = report.status === 'success' ? '成功'
            : report.status === 'partial' ? '部分成功'
                : report.status === 'no-target' ? '跳过'
                    : '失败';
        const reasonText = ({
            'target-empty': '目标人数均为0',
            'manager-unavailable': '管理器未就绪',
            'interface-unavailable': '接口未就绪',
            'no-one-star-general': '没有可选的一阶武将',
            'runtime-error': '执行异常',
			'account-not-ready': '当前账号未识别，已阻止发包',
			'account-mismatch': '实时快照账号与当前账号不一致，已阻止发包',
            'local-general-state-unstable': '本地武将列表未稳定，已阻止发包',
            'local-upgrade-state-not-reset': '本地已有高于一阶武将，已阻止本轮全部升阶',
			'roster-not-scanned': '实时拥有武将快照未就绪，已阻止发包',
			'roster-sentinel-unavailable': '实时快照目标前缀状态无法稳定读取，已阻止发包'
        })[report.reason] || '';
        const stages = report.stages.map((stage) => {
            const details = [];
            if (stage.alreadySatisfiedCount > 0) details.push(`当前已达标${stage.alreadySatisfiedCount}`);
            if (stage.transitionConfirmedCount > 0) {
                const ids = stage.confirmedIds.slice(0, 12);
                details.push(`实时捕获${stage.transitionConfirmedCount}${ids.length ? `（ID:${ids.join(',')}）` : ''}`);
            }
            if (stage.unconfirmedCount > 0) details.push(`单次窗口未捕获${stage.unconfirmedCount}`);
            if (stage.blockedCount > 0) details.push(`前层未达标${stage.blockedCount}`);
			if (stage.missingCount > 0) details.push(`实时快照不足${stage.missingCount}`);
            if (stage.unsentCount > 0) details.push(`总确认预算到期未发${stage.unsentCount}`);
			if (stage.materialFallbackCount > 0) {
				const fallbackTotals = new Map();
				for (const item of stage.materialPlans.filter((entry) => entry.fallback && entry.name)) {
					fallbackTotals.set(item.name, (fallbackTotals.get(item.name) || 0) + Math.max(0, Number(item.count) || 0));
				}
				const fallbackText = Array.from(fallbackTotals.entries()).map(([name, count]) => `${name}×${count}`).join('/');
				details.push(`材料回退${stage.materialFallbackCount}${fallbackText ? `（${fallbackText}）` : ''}`);
			}
			if (stage.materialUnavailableCount > 0) details.push(`已知材料不足${stage.materialUnavailableCount}`);
            if (stage.blockedReason === 'previous-stage-state-not-refreshed') details.push('前层未确认，已阻止继续升阶');
            return `${stage.from}→${stage.to} 本轮满足${stage.confirmedCount}/${stage.targetCount}${details.length ? `（${details.join('、')}）` : ''}`;
        });
		const preflightText = report.preflight
			? report.preflight.sentinelId
				? `；预检：实时快照${report.preflight.snapshot ? `${report.preflight.snapshot.acceptedCount}/${report.preflight.snapshot.rawCount}名、拒绝${report.preflight.snapshot.rejectedCount}名` : `${report.preflight.rosterCount}名`}、核对前缀${report.preflight.checkedCount || 1}名、首ID=${report.preflight.sentinelId}为${report.preflight.sentinelStar || '?'}阶、${report.preflight.stable ? '前缀稳定' : '前缀未稳定'}、${report.preflight.waitedMs}ms`
				: `；预检：${report.preflight.stable ? '列表稳定' : '列表未稳定'}、${report.preflight.waitedMs}ms`
            : '';
        const executionText = report.execution
			? `；调度：并发${report.execution.workerCount}、峰值在途${report.execution.maxActiveConfirmations}、新武将间隔${report.execution.sendIntervalMs}ms、事件监听${report.execution.eventMonitorInstalled ? '已装' : '未装'}、事件确认${report.execution.eventObservedSuccessCount}次、迟到回收${report.execution.lateConfirmedCount}次、整体最小间隔${report.execution.minimumObservedSendGapMs}ms、耗时${report.execution.elapsedMs}ms`
            : '';
        return `${statusText}${stages.length ? `：${stages.join('；')}` : reasonText ? `：${reasonText}` : ''}${reasonText && stages.length ? `；${reasonText}` : ''}${preflightText}${executionText}`;
    }

    function classifyDailyRewardTraceItems(selection, result) {
        const source = result && typeof result === 'object' ? result : {};
        const groups = {
            done: Array.isArray(source.done) ? source.done.map(String) : [],
            requested: Array.isArray(source.requested) ? source.requested.map(String) : [],
            skipped: Array.isArray(source.skipped) ? source.skipped.map(String) : [],
            errors: Array.isArray(source.errors) ? source.errors.map(String) : []
        };
        const matchesLabels = (text, labels) => labels.some((label) => String(text).includes(label));
        const output = {};
        for (const definition of DAILY_REWARD_ITEM_DEFS) {
            const key = definition.key;
            if (['mailClaim', 'giftCodes', 'blackMagicOrb'].includes(key)) continue;
            const labels = DAILY_REWARD_TRACE_LABELS[key] || [definition.label];
            if (key === 'generalUpgrade' && selection && selection[key] === true && source.generalUpgrade) {
                const report = compactGeneralUpgradeReport(source.generalUpgrade);
                output[key] = {
                    label: definition.label,
                    enabled: true,
                    status: report?.success === true ? 'server-confirmed'
                        : report?.status === 'partial' ? 'partial-confirmed'
                            : report?.status === 'unconfirmed' ? 'timeout-or-unconfirmed'
                                : report?.status === 'no-target' ? 'not-claimable' : 'failed',
                    evidence: [{ group: 'result', text: describeGeneralUpgradeReport(report) }]
                };
                continue;
            }
            const evidence = [];
            for (const [group, values] of Object.entries(groups)) {
                for (const text of values) {
                    if (matchesLabels(text, labels)) evidence.push({ group, text });
                }
            }
            let status = selection && selection[key] === true ? 'no-result' : 'disabled';
            if (evidence.some((item) => item.group === 'done')) status = 'server-confirmed';
            else if (evidence.some((item) => item.group === 'skipped' && /服务器拒绝|Result\s*(?:=|:)?\s*\d+/i.test(item.text))) status = 'server-rejected';
            else if (evidence.some((item) => /官方活动数据未加载/.test(item.text))) status = 'official-data-unavailable';
            else if (evidence.some((item) => /数据.*(?:未就绪|未初始化)|任务字典.*未加载/.test(item.text))) status = 'data-not-ready';
            else if (evidence.some((item) => item.group === 'requested' || /未确认|未收到.*回包|请求已发送.*未收到/.test(item.text))) status = 'timeout-or-unconfirmed';
            else if (evidence.some((item) => item.group === 'errors')) status = 'local-or-request-error';
            else if (evidence.some((item) => /管理器无|接口无|接口不完整|监听接口无|状态接口无/.test(item.text))) status = 'interface-unavailable';
            else if (evidence.length) status = 'not-claimable';
            output[key] = {
                label: definition.label,
                enabled: selection && selection[key] === true,
                status,
                evidence
            };
        }
        return output;
    }

    function readDailyRewardTrace() {
        const stored = storageGet(DAILY_REWARD_TRACE_KEY, []);
        return Array.isArray(stored) ? stored.slice(-DAILY_REWARD_TRACE_LIMIT) : [];
    }

    function readDailyRewardTraceSummary() {
        const stored = storageGet(DAILY_REWARD_TRACE_SUMMARY_KEY, null);
        return stored && typeof stored === 'object' && !Array.isArray(stored)
            ? stored
            : { schema: 'sgsol-daily-reward-trace-summary/v1', totalCycles: 0, updatedAt: '', items: {} };
    }

    function updateDailyRewardTraceSummary(entry) {
        const summary = readDailyRewardTraceSummary();
        summary.schema = 'sgsol-daily-reward-trace-summary/v1';
        summary.totalCycles = Math.max(0, Number(summary.totalCycles) || 0) + 1;
        summary.updatedAt = entry.at;
        if (!summary.items || typeof summary.items !== 'object' || Array.isArray(summary.items)) summary.items = {};
        for (const [key, item] of Object.entries(entry.items || {})) {
            const previous = summary.items[key] && typeof summary.items[key] === 'object'
                ? summary.items[key]
                : { label: item.label, enabledCycles: 0, statuses: {} };
            previous.label = item.label;
            if (item.enabled) previous.enabledCycles = Math.max(0, Number(previous.enabledCycles) || 0) + 1;
            if (!previous.statuses || typeof previous.statuses !== 'object' || Array.isArray(previous.statuses)) previous.statuses = {};
            previous.statuses[item.status] = Math.max(0, Number(previous.statuses[item.status]) || 0) + 1;
            previous.lastStatus = item.status;
            previous.lastAt = entry.at;
            previous.lastCycleId = entry.cycleId;
            previous.lastEvidence = Array.isArray(item.evidence) ? item.evidence.slice(-4) : [];
            summary.items[key] = previous;
        }
        storageSet(DAILY_REWARD_TRACE_SUMMARY_KEY, summary);
    }

    function appendDailyRewardTrace(selection, result, before, after, frequency) {
        if (!TOP_WINDOW) return null;
        try {
            const state = readState();
            const entry = {
                schema: 'sgsol-daily-reward-trace/v1',
                at: new Date().toISOString(),
                scriptVersion: VERSION,
                cycleId: String(state.cycleId || ''),
                phase: String(state.phase || ''),
                frequency: frequency === 'cycle' ? 'cycle' : 'day',
                ready: result && result.ready === true,
                error: result && result.ready === false ? String(result.error || 'not-ready') : '',
                items: classifyDailyRewardTraceItems(selection, result),
                raw: {
                    done: Array.isArray(result?.done) ? result.done.map(String) : [],
                    requested: Array.isArray(result?.requested) ? result.requested.map(String) : [],
                    skipped: Array.isArray(result?.skipped) ? result.skipped.map(String) : [],
                    errors: Array.isArray(result?.errors) ? result.errors.map(String) : []
                },
                officerTasks: compactOfficerTaskReport(result?.officerTasks),
                generalUpgrade: compactGeneralUpgradeReport(result?.generalUpgrade),
                settleWaitMs: Math.max(0, Number(result?.settleWaitMs) || 0),
                before: compactDailyRewardStateSnapshot(before),
                after: compactDailyRewardStateSnapshot(after)
            };
            const recent = readDailyRewardTrace();
            recent.push(entry);
            storageSet(DAILY_REWARD_TRACE_KEY, recent.slice(-DAILY_REWARD_TRACE_LIMIT));
            updateDailyRewardTraceSummary(entry);
            lastDailyRewardTraceEntry = entry;
            return entry;
        } catch (_) {
            // 追踪日志是旁路诊断；任何文件异常都不能改变领取或退出流程。
            return null;
        }
    }

    function todayStamp() {
        const d = new Date();
        return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;
    }

    async function runDailyRewardsOncePerDay(bridge) {
        // 每项独立开关；全灭时完全不调用日常奖励桥。
        try {
            const { selection, frequency: freq, dailyFrequencyDue } = dailyRewardBridgeSelection();
            // 开黑魔珠属于同一组 UI 开关，但必须在每个账号登录后重新查官方进度，
            // 不受“每天一次”日戳限制；它在本函数之后由独立兑换步骤执行。
            // 官阶链和武将升阶固定每轮执行；全局“每天/每轮”只控制其他普通日常项目。
            const enabledItems = enabledDailyRewardItems(selection).filter((item) => !['mailClaim', 'giftCodes', 'blackMagicOrb'].includes(item.key));
            if (!enabledItems.length) return '';
            if (!bridge || typeof bridge.claimDailyRewards !== 'function') return '；[日常奖励] 桥未提供接口（需重启微端注入新版）';
            const res = await Promise.resolve(bridge.claimDailyRewards(selection));
            appendDailyRewardTrace(
                selection,
                res,
                res && res.officerBefore ? res.officerBefore : null,
                res && res.officerAfter ? res.officerAfter : null,
                freq
            );
            if (!res || res.ready === false) return `；[日常奖励] 未执行（${res?.error || '游戏未就绪'}），下轮再试`;
            // 各项目独立执行：某一项接口尚未注册时，只让该项下轮重试，不能抹掉其他项目本轮的真实结果。
            const notReadyItems = (res.skipped || []).filter((x) => /管理器无|接口无|接口不完整/.test(x));
            const notReady = notReadyItems.length;
            // “每天一次”只有在全部已点亮项目均完成接口检查后才落日戳，避免未就绪项目漏领一整天。
            const ranDailyFrequencyItem = dailyFrequencyDue && enabledItems.some((item) => !DAILY_REWARD_FIXED_EACH_CYCLE_KEYS.has(item.key));
            if (freq === 'day' && ranDailyFrequencyItem && notReady === 0 && !(res.errors || []).length && !(res.requested || []).length && !(res.skipped || []).some(text => /拒绝|未确认|未返回|未收到|失败/.test(text))) storageSet(DAILY_LAST_KEY, todayStamp());
			// 军典档位、节钺令与武将升阶会在“本轮功能结果”中各显示一次，这里不再重复铺开。
            const withoutSummarizedFeatures = (values) => (Array.isArray(values) ? values : [])
                .map(String)
				.filter((text) => !text.includes('武将升阶') && !text.includes('军典档位一键') && !text.includes('节钺令'));
            const doneText = withoutSummarizedFeatures(res.done).join('、') || '无';
            const requestedText = withoutSummarizedFeatures(res.requested).join('、') || '无';
            const skipText = withoutSummarizedFeatures(res.skipped).join('、') || '无';
            const otherErrors = withoutSummarizedFeatures(res.errors);
            const errText = otherErrors.length ? `；异常：${otherErrors.join('、')}` : '';
            const retryText = notReady
                ? `；接口待就绪：${notReadyItems.join('、')}（仅这些项目下轮重试）`
                : '';
            return `；[日常奖励·独立${enabledItems.length}项·${freq === 'cycle' ? '全部每轮' : '官阶/升阶每轮，普通每天'}] 确认成功：${doneText}；待确认：${requestedText}；跳过：${skipText}${retryText}${errText}`;
        } catch (error) {
            return `；[日常奖励] 异常：${error instanceof Error ? error.message : String(error)}`;
        }
    }

    async function exchangeBlackMagicOrbsEachCycleResult(bridge) {
        try {
            if (readDailyRewardItems().blackMagicOrb !== true) return { text: '', status: 'disabled', success: true, enabled: false };
            if (!bridge || typeof bridge.exchangeBlackMagicOrbs !== 'function') {
                return { text: '；[竞猜币兑换] 桥未提供接口（需重启微端注入新版）', status: 'bridge-unavailable', success: false, enabled: true };
            }
            const result = await withTimeout(
                Promise.resolve(bridge.exchangeBlackMagicOrbs()),
                8000,
                '竞猜币兑换执行超过 8 秒'
            );
            try { pushRawLog('black-magic-orb-exchange', JSON.stringify(result || {})); } catch (_) {}
            if (!result || result.ready === false) {
                return { text: `；[竞猜币兑换] 未执行（${result?.status || result?.error || '游戏未就绪'}），下轮再试`, status: String(result?.status || result?.error || 'not-ready'), success: false, enabled: true };
            }
            const before = Math.max(0, Number(result.beforeTimes || 0));
            const after = Math.max(0, Number(result.afterTimes || 0));
            const sent = Math.max(0, Number(result.sentExchanges || 0));
            if (result.status === 'weekly-limit-reached') {
                return { text: `；[竞猜币兑换] 开黑魔珠本周已兑换 ${after}/2，跳过发包`, status: result.status, success: true, enabled: true, before, after, sent };
            }
            if (result.status === 'activity-outside-time') {
                return { text: '；[竞猜币兑换] 开黑魔珠活动不在开放时间，跳过发包', status: result.status, success: false, enabled: true, before, after, sent };
            }
            if (result.confirmed) {
                return { text: `；[竞猜币兑换] 开黑魔珠服务器确认完成 ${Math.max(0, after - before) || sent} 次（周进度 ${after}/2）`, status: 'server-confirmed', success: true, enabled: true, before, after, sent };
            }
            if (sent > 0) {
                return { text: `；[竞猜币兑换] 已请求开黑魔珠 ${sent} 次，4 秒内未确认（周进度 ${before}→${after}）`, status: 'sent-unconfirmed', success: false, enabled: true, before, after, sent };
            }
            return { text: `；[竞猜币兑换] 未发包（${result.status || result.error || '未知状态'}）`, status: String(result.status || result.error || 'not-sent'), success: false, enabled: true, before, after, sent };
        } catch (error) {
            return { text: `；[竞猜币兑换] 异常：${error instanceof Error ? error.message : String(error)}`, status: 'error', success: false, enabled: true };
        }
    }

    

    function giftCodeUtf8Length(value) {
        const text = String(value || '');
        if (typeof TextEncoder === 'function') return new TextEncoder().encode(text).length;
        return unescape(encodeURIComponent(text)).length;
    }

    function normalizeGiftCodes(value) {
        const rawCodes = Array.isArray(value)
            ? value
            : String(value || '').split(/[\r\n,，;；]+/);
        const seen = new Set();
        return rawCodes.map((code) => String(code || '').trim()).filter((code) => {
            if (!code || /\s/.test(code) || giftCodeUtf8Length(code) > 64 || seen.has(code)) return false;
            seen.add(code);
            return true;
        }).slice(0, 50);
    }

    function normalizeGiftCodeEntry(value, index = 0, strict = false) {
        try {
            const source = typeof value === 'string' ? { code: value } : value;
            if (!source || typeof source !== 'object' || Array.isArray(source)) throw new Error(`第 ${index + 1} 项不是对象或字符串`);
            const code = String(source.code ?? source.CDKey ?? '').trim();
            if (!code) throw new Error(`第 ${index + 1} 项缺少 code`);
            if (/\s/.test(code)) throw new Error(`兑换码“${code}”包含空白字符`);
            if (giftCodeUtf8Length(code) > 64) throw new Error(`兑换码“${code}”超过协议 64 字节上限`);

            const rawGiftId = Number(source.giftId ?? source.GiftID ?? 0);
            if (!Number.isInteger(rawGiftId) || rawGiftId < 0 || rawGiftId > 65535) {
                throw new Error(`兑换码“${code}”的 giftId 超出 0~65535`);
            }
            const rawType = Number(source.type ?? source.Type ?? 0);
            if (!Number.isInteger(rawType) || rawType < 0 || rawType > 255) {
                throw new Error(`兑换码“${code}”的 type 超出 0~255`);
            }
            const route = String(source.route || 'auto');
            if (!['auto', 'direct', 'window'].includes(route)) {
                throw new Error(`兑换码“${code}”的 route 只能是 auto/direct/window`);
            }
            const rawStatus = String(source.status || 'pending');
            const rawLastResult = String(source.lastResult || '');
            const legacyServerFeedback = /^(?:server-|submitted-unconfirmed)/.test(rawStatus) ||
                /服务器(?:确认成功|明确失败|提示已领取|回包超时)|Result=\d+/.test(rawLastResult);

            return {
                id: String(source.id || `cdk-${index + 1}`),
                code,
                giftId: rawGiftId,
                type: rawType,
                route,
                enabled: source.enabled !== false,
                source: String(source.source || (typeof value === 'string' ? 'legacy' : 'saved')),
                note: String(source.note || ''),
                attempts: Math.max(0, Math.min(MAX_GIFT_CODE_ATTEMPTS, Number(source.attempts || 0))),
                status: legacyServerFeedback ? 'ready' : rawStatus,
                lastResult: legacyServerFeedback ? '' : rawLastResult,
                lastResultCode: !legacyServerFeedback && source.lastResultCode != null && Number.isFinite(Number(source.lastResultCode))
                    ? Number(source.lastResultCode)
                    : null,
                updatedAt: Number(source.updatedAt || 0)
            };
        } catch (error) {
            if (strict) throw error;
            return null;
        }
    }

    function readGiftCodeQueue() {
        const saved = storageGet(GIFT_CODE_QUEUE_KEY, null);
        const source = Array.isArray(saved) ? saved : DEFAULT_GIFT_CODES.map((code) => ({ code, source: 'default' }));
        const seen = new Set();
        return source.map((entry, index) => normalizeGiftCodeEntry(entry, index, false)).filter((entry) => {
            if (!entry || seen.has(entry.code)) return false;
            seen.add(entry.code);
            return true;
        }).slice(0, 50);
    }

    function writeGiftCodeQueue(queue) {
        const normalized = (Array.isArray(queue) ? queue : [])
            .map((entry, index) => normalizeGiftCodeEntry(entry, index, false))
            .filter(Boolean)
            .slice(0, 50);
        storageSet(GIFT_CODE_QUEUE_KEY, normalized);
        if (giftCodeStatus) giftCodeStatus.textContent = formatGiftCodeQueueStatus();
    }

    function parseGiftCodeJsonPayload(input) {
        let payload = input;
        if (typeof payload === 'string') {
            try {
                payload = JSON.parse(payload);
            } catch (error) {
                throw new Error(`JSON 解析失败：${error instanceof Error ? error.message : String(error)}`);
            }
        }
        if (Array.isArray(payload)) payload = { schema: GIFT_CODE_JSON_SCHEMA, codes: payload };
        if (!payload || typeof payload !== 'object') throw new Error('CDK JSON 顶层必须是对象或数组');
        if (payload.schema && payload.schema !== GIFT_CODE_JSON_SCHEMA) {
            throw new Error(`不支持的 CDK JSON schema：${String(payload.schema)}`);
        }
        const sourceCodes = Array.isArray(payload.codes) ? payload.codes : (Array.isArray(payload.cdks) ? payload.cdks : null);
        if (!sourceCodes) throw new Error('CDK JSON 缺少 codes 数组');
        if (sourceCodes.length > 50) throw new Error('CDK JSON 最多导入 50 个兑换码');

        const seen = new Set();
        const codes = sourceCodes.map((entry, index) => normalizeGiftCodeEntry(entry, index, true)).filter((entry) => {
            if (seen.has(entry.code)) return false;
            seen.add(entry.code);
            return true;
        }).map((entry) => ({
            ...entry,
            source: 'json',
            attempts: 0,
            status: 'imported',
            lastResult: '',
            updatedAt: Date.now()
        }));
        return {
            schema: GIFT_CODE_JSON_SCHEMA,
            accountId: String(payload.accountId || ''),
            codes
        };
    }

    

    

    

    

    

    function formatGiftCodeQueueStatus() {
        const queue = readGiftCodeQueue();
        if (!queue.length) return '未设置兑换码';
        const enabledCount = queue.filter((entry) => entry.enabled).length;
        const jsonCount = queue.filter((entry) => entry.source === 'json').length;
        const latest = queue.slice().sort((left, right) => Number(right.updatedAt || 0) - Number(left.updatedAt || 0))[0];
        const latestResult = String(latest?.lastResult || '').trim();
        const compactResult = latestResult.length > 56 ? `${latestResult.slice(0, 56)}…` : latestResult;
        return `共 ${queue.length} 个（启用 ${enabledCount}，JSON ${jsonCount}）；每码每轮 ${MAX_GIFT_CODE_ATTEMPTS} 次${compactResult ? `；最近：${compactResult}` : ''}`;
    }

    

    

    

    

    async function redeemGiftCodesEachCycle(bridge) {
        const queue = readGiftCodeQueue();
        const entries = queue.filter(entry => entry.enabled);
        if (!entries.length) return '';
        if (!bridge || typeof bridge.redeemGiftCode !== 'function') return '；兑换码：接口未就绪';
        const cycleId = readState().cycleId;
        const accountId = currentGeneralUpgradeAccountId();
        const pending = [];
        for (const entry of entries) {
            if (!readState().enabled || readState().cycleId !== cycleId) break;
            const direct = entry.route === 'direct' || entry.giftId > 0 || entry.route !== 'window' && entry.code.length < 16;
            const task = Promise.resolve().then(() => bridge.redeemGiftCode(entry)).then(
                result => ({ entry, result }), error => ({ entry, result: { submitted: false, error: String(error.message || error) } }));
            pending.push(task);
            // Official window requests share a single UI; finish one before opening the next.
            if (!direct) await task;
            if (!direct && entry !== entries[entries.length - 1]) {
                await new Promise(resolve => setTimeout(resolve, GIFT_CODE_BETWEEN_MS));
            }
        }
        const results = await Promise.all(pending);
        if (readState().cycleId !== cycleId || currentGeneralUpgradeAccountId() !== accountId) return '；兑换码：旧轮结果未写入当前账号';
        const latest = readGiftCodeQueue();
        const summaries = [];
        for (const { entry, result } of results) {
            const index = latest.findIndex(item => item.code === entry.code && item.giftId === entry.giftId && item.type === entry.type && item.route === entry.route);
            if (index < 0) continue;
            const label = !result.submitted ? '请求失败' : result.accepted ? '确认成功' : result.alreadyClaimed ? '已领取' : result.confirmed ? '服务器拒绝' : '已发送未确认';
            latest[index] = { ...latest[index], attempts: result.submitted ? 1 : 0,
                status: result.serverState || (result.submitted ? 'submitted-unconfirmed' : 'request-error'),
                lastResult: label, lastResultCode: result.resultCode == null ? null : result.resultCode,
                lastRoute: result.route || entry.route, updatedAt: Date.now() };
            summaries.push(`“${entry.code}”：${label}`);
        }
        writeGiftCodeQueue(latest);
        return '；兑换码：' + summaries.join('、');
    }

    

    

    

    

    

    function readState() {
        const saved = storageGet(STATE_KEY, null);
        const state = saved && typeof saved === 'object'
            ? { ...defaultState, ...saved }
            : { ...defaultState };
        // 2.8.x 不再支持调相、登录提前和失败加时；始终清理旧轮次字段，避免旧状态被误读。
        state.lastWaitExtraMs = 0;
        state.lastWaitExtraKind = '';
        for (const key of Object.keys(state)) if (key.indexOf('phaseTune') === 0) delete state[key];
        if (Number(state.scheduleVersion) !== 2) {
            if (state.enabled && ['idle', 'login', 'login_submitted'].includes(state.phase) && state.offlineScheduleAnchorAt) {
                const target = Number(state.offlineScheduleAnchorAt) + readCycleMs();
                state.targetLoginAt = target;
                state.scheduledEntryAt = target;
                if (state.phase === 'idle') state.nextRunAt = Date.now();
            }
            state.scheduleVersion = 2;
        }
        return { ...state, claimMode: 'all' };
    }

    function writeState(patch, options = {}) {
        const current = readState();
        if (current.phase === 'recovery_wait' && !options.allowRecoveryTransition) {
            return current;
        }
        const next = { ...current, ...patch };
        const bridge = mailAssistantSharedBridge();
        if (bridge && Number(bridge.version) >= 7) {
            storageSet(STATE_KEY, { ...patch, scheduleVersion: 2 }, { patch: true,
                expectedCycleId: current.cycleId || '',
                requireEnabled: current.enabled === true && patch.enabled !== false });
        } else storageSet(STATE_KEY, next);
        const saved = readState();
        renderPanel(saved);
        return saved;
    }

    function readLogs() {
        const logs = storageGet(LOG_KEY, []);
        return Array.isArray(logs) ? logs : [];
    }

    function readTotalLogs() {
        const logs = storageGet(TOTAL_LOG_KEY, null);
        // 首次升级时用原来的可见记录作为总记录初始值，避免丢掉已有记录。
        return Array.isArray(logs) ? logs : readLogs();
    }

    function reportMailAssistantWatchdog(state = readState(), entries = readTotalLogs()) {
        try {
            const bridge = pageWindow && pageWindow.__SGSOL_BRIDGE__;
            if (!bridge || typeof bridge.reportMailAssistantProgress !== 'function') return;
            const officerTab = readOfficerLinkTab();
            const listenerOnly = officerTab.mode === 'listener';
            const logs = Array.isArray(entries) ? entries : [];
            const latest = logs.length ? logs[logs.length - 1] : null;
            const fingerprint = latest
                ? [
                    logs.length,
                    Number(latest.at || 0),
                    String(latest.cycleId || ''),
                    String(latest.phase || ''),
                    String(latest.message || '').slice(0, 320)
                ].join('|')
                : 'empty-log';
            bridge.reportMailAssistantProgress({
                // 监听端与接收端可同时启动两个微端进程，但二者会看到同一份共享状态。
                // 监听端只负责好友官阶观察，绝不能把接收端的运行轮次上报给自己的主进程守护。
                enabled: listenerOnly ? false : state && state.enabled === true,
                phase: listenerOnly ? 'officer_listener' : String(state && state.phase || ''),
                cycleId: listenerOnly ? '' : String(state && state.cycleId || ''),
                nextRunAt: listenerOnly ? 0 : Math.max(0, Number(state && state.nextRunAt) || 0),
                fingerprint,
                recordCount: logs.length,
                latestRecordAt: latest ? Math.max(0, Number(latest.at) || 0) : 0
            });
        } catch (_) {
            // 守护上报只能辅助恢复，任何异常都不能打断正常领取。
        }
    }

    function isRoutineLoginLogoutMessage(message) {
        return /^(?:已拦截重复的程序化登录提交|本轮登录请求已经发送，等待结果|登录请求已发送，本轮不会再次提交|已选择(?:经典版|重制版)，等待游戏加载|已选择(?:经典版|重制版)，正在点击进入（第 \d+\/\d+ 次；仍停留此页会自动重试）|已识别(?:经典版|重制版)游戏页面，继续一键领取|检测到(?:经典版|重制版)入口仍停留在登录页，已恢复自动点击重试|检测到官网账号仍处于登录状态，继续确认退出|正在退出官方账号|已确认官方账号退出(?:；周期从退出请求发送时刻开始计算)?|未找到官方退出按钮，正在刷新登录页|刷新登录页后仍未找到官方退出按钮)$/.test(String(message || '').trim());
    }

    function persistLogEntry(entry) {
        if (!entry || isRoutineLoginLogoutMessage(entry.message)) {
            return { visible: readLogs(), total: readTotalLogs() };
        }
        const visible = readLogs()
            .filter((item) => !isRoutineLoginLogoutMessage(item?.message))
            .map(normalizeLogEntry)
            .filter(isPanelLog);
        const total = readTotalLogs().filter((item) => !isRoutineLoginLogoutMessage(item?.message));
        const normalizedEntry = normalizeLogEntry(entry);
        if (isPanelLog(normalizedEntry)) visible.push(normalizedEntry);
        const previous = total[total.length - 1];
        if (previous && previous.cycleId === entry.cycleId && previous.phase === entry.phase && previous.message === entry.message) {
            return { visible, total };
        }
        total.push(entry);
        const nextVisible = visible.slice(-VISIBLE_LOG_LIMIT);
        const nextTotal = total.slice(-TOTAL_LOG_LIMIT);
        storageSet(LOG_KEY, nextVisible);
        storageSet(TOTAL_LOG_KEY, nextTotal);
        return { visible: nextVisible, total: nextTotal };
    }

    function isTransientGiftCodeProgressMessage(message) {
        return /^正在领取兑换码“[^”]+”[\s\S]*等待服务器回包/.test(String(message || '').trim());
    }

    function isTransientJsonArchiveReadinessMessage(message) {
        return /^JSON 白名单准备中：[\s\S]*保持在游戏页等待/.test(String(message || '').trim());
    }

    function freeBlessReference(message) {
        const text = String(message || '');
        const match = text.match(/免费祈福(?:(?:\([^；、]*\))|(?::[^；、]*))/);
        if (!match) return null;
        const detail = match[0].trim();
        const isDailyRewardException = /异常：[^；]*免费祈福:/.test(text);
        if (isDailyRewardException || /服务器拒绝|发包或监听失败|配置请求失败|活动入口配置\d+(?:\.\d+)?秒内未返回|活动入口无|活动入口未找到|免费状态已变化|请求异常|请求错误|接口不完整|接口无|管理器无|监听接口无|状态接口无/.test(detail)) {
            return { level: 'error', status: 'error', summary: '祈福异常', detail };
        }
        if (/服务器确认成功|状态确认已领取/.test(detail)) {
            return { level: 'success', status: 'confirmed', summary: '祈福成功', detail };
        }
        if (/未收到奖励回包|结果未确认|未捕获回包|请求已发送/.test(detail)) {
            return { level: 'success', status: 'unconfirmed', summary: '祈福未确认', detail };
        }
        return { level: 'info', status: 'not-claimable', summary: '祈福未满足条件', detail };
    }

    function shouldPersistLog(state) {
        const message = String(state?.message || '');
        if (isRoutineLoginLogoutMessage(message) || isTransientGiftCodeProgressMessage(message)) return false;
        if (isTransientJsonArchiveReadinessMessage(message)) return false;
        const isRuntimeRecovery = /(?:经典版|重制版|所选版本)加载期间已退回登录表单|(?:经典版|重制版|所选版本)加载超过 (?:30|60) 秒无结果：Electron 已刷新|检测到(?:经典版|重制版|所选版本) runtime 连续|(?:经典版|重制版|所选版本) runtime 刷新后仍未就绪/.test(message);
        const isFailureOrRetry = /失败|错误|未就绪|重试|超时|弹窗|未找到|请求出错|领取流程异常|异常\s*[1-9]\d*\s*次|微端重启|黑屏恢复/.test(message);
        /* 邮件附件记录是当前唯一的龙珠统计来源，始终保留这类轮次摘要。 */
        const isTrackedClaimSummary = /邮件附件记录/.test(message);
        const isGiftCodeActivity = /兑换码(?:[“”]|本轮|：)|正在(?:兑换|领取)兑换码/.test(message);
        const isFreeBlessOutcome = ['success', 'error'].includes(freeBlessReference(message)?.level);
        const isStrictFeatureOutcome = /\[本轮功能结果\]|\[本轮总判定\]/.test(message);
        // 修复：把“未领到 / 无可领邮件（未刷新）”这类判因信息也保留，便于回看每轮为什么没领到。
        const isClaimOutcome = /领到|到账|无可领邮件|未刷新|未确认|未增加|龙珠/.test(message);
        return isRuntimeRecovery || isFailureOrRetry || isTrackedClaimSummary || isGiftCodeActivity || isFreeBlessOutcome || isStrictFeatureOutcome || isClaimOutcome;
    }

    function appendLog(state) {
        if (!shouldPersistLog(state)) return;
        const level = classifyLogMessage(state.message, state.phase);
        const stored = persistLogEntry({
            at: state.messageAt,
            cycleId: state.cycleId,
            phase: state.phase,
            message: state.message,
            level,
            summary: compactLogSummary(state.message, level)
        });
        lastLogRenderSignature = '';
        refreshLogButtonLabel(stored.total);
    }

    const LOG_LEVEL_META = Object.freeze({
        error: { label: '错误', color: '#ff9a8e', border: '#8e4942', background: 'rgba(112,45,39,.28)' },
        warning: { label: '正常', color: '#94d39a', border: '#456f49', background: 'rgba(45,91,52,.24)' },
        recovered: { label: '已恢复', color: '#8fc8d8', border: '#466d78', background: 'rgba(45,82,91,.24)' },
        success: { label: '正常', color: '#94d39a', border: '#456f49', background: 'rgba(45,91,52,.24)' },
        info: { label: '过程', color: '#b9ad94', border: '#5f5545', background: 'rgba(70,62,50,.22)' }
    });

    function isExplicitServerFailureMessage(message) {
        const text = String(message || '');
        const jsonMailFeedback = text.match(/JSON 专用自动化完成：[\s\S]*?服务器确认成功\s*(\d+)、已领取\s*(\d+)、失败\s*(\d+)、超时\/未确认\s*(\d+)/);
        if (jsonMailFeedback) {
            const already = Number(jsonMailFeedback[2]) || 0;
            const rejected = Number(jsonMailFeedback[3]) || 0;
            if (already > 0 || rejected > 0) return true;
        }
        const countNeutralText = text
            .replace(/已领取\s*0(?:\s*封)?/g, '')
            .replace(/失败\s*0(?:\s*封)?/g, '');
        return /server-reported-already-(?:claimed|handled)|server-rejected|Result\s*(?:=|:)?\s*15\b|服务器(?:明确失败|明确返回失败|明确判定失败|提示已领取|返回已领取|表示已经领取|拒绝(?:领取)?)/i.test(countNeutralText);
    }

    function classifyLogMessage(message, phase = '') {
        const text = String(message || '');
		if (String(phase || '') === 'black-magic-orb-exchange') return 'info';
        if (/(?:经典版|重制版|所选版本)加载期间已退回登录表单|(?:经典版|重制版|所选版本)加载超过 (?:30|60) 秒无结果：Electron 已刷新|检测到(?:经典版|重制版|所选版本) runtime 连续|(?:经典版|重制版|所选版本) runtime 刷新后仍未就绪/.test(text)) return 'recovered';
        const freeBless = freeBlessReference(text);
        const strictFeatureResult = text.match(/\[本轮总判定\]\s*(成功|异常)/);
        if (strictFeatureResult) return strictFeatureResult[1] === '成功' ? 'success' : 'error';
        const jsonMailFeedback = text.match(/JSON 专用自动化完成：[\s\S]*?服务器确认成功\s*(\d+)、已领取\s*(\d+)、失败\s*(\d+)、超时\/未确认\s*(\d+)/);
        if (jsonMailFeedback) {
            const accepted = Number(jsonMailFeedback[1]) || 0;
            const already = Number(jsonMailFeedback[2]) || 0;
            const rejected = Number(jsonMailFeedback[3]) || 0;
            const unconfirmed = Number(jsonMailFeedback[4]) || 0;
            if (already > 0 || rejected > 0 || freeBless?.level === 'error') return 'error';
            if (accepted > 0 || unconfirmed > 0 || freeBless?.level === 'success') return 'success';
            return 'error';
        }
        if (freeBless?.level === 'error') return 'error';
        if (freeBless?.level === 'success') return 'success';
        const countNeutralText = text
            .replace(/已领取\s*0(?:\s*封)?/g, '')
            .replace(/失败\s*0(?:\s*封)?/g, '')
            .replace(/超时\/未确认\s*0(?:\s*封)?/g, '')
            .replace(/超时\s*0(?:\s*封)?/g, '')
            .replace(/(?:其他)?未确认\s*0(?:\s*封)?/g, '')
            .replace(/异常\s*0\s*次/g, '');
        if (isExplicitServerFailureMessage(text)) return 'error';
        if (/失败|错误|异常|未领取|未领到|未收到服务器龙珠奖励记录|无可领邮件|未刷新|请求异常|请求错误|请求出错/.test(countNeutralText)) return 'error';
        if (/server-accepted|服务器确认成功|no-response-timeout|超时|未确认|未捕获回包/.test(countNeutralText)) return 'success';
        return 'error';
    }

    function compactLogSummary(message, level = 'info') {
        const text = String(message || '').trim().replace(/\s+/g, ' ');
        const freeBless = freeBlessReference(text);
        const strictFeature = text.match(/\[本轮功能结果\][\s\S]*?\[本轮总判定\]\s*(成功|异常)（(\d+)\/(\d+) 项成功）/);
        if (strictFeature) return `功能 ${strictFeature[1]}｜${strictFeature[2]}/${strictFeature[3]} 项成功`;
        const jsonClaim = text.match(/JSON 专用自动化完成：已发送\s*(\d+)\/(\d+)\s*封；服务器确认成功\s*(\d+)、已领取\s*(\d+)、失败\s*(\d+)、超时\/未确认\s*(\d+)/);
        if (jsonClaim) {
            return `发送 ${jsonClaim[1]}/${jsonClaim[2]}｜成功 ${jsonClaim[3]}｜已领取 ${jsonClaim[4]}｜失败 ${jsonClaim[5]}｜超时未确认 ${jsonClaim[6]}${freeBless && freeBless.level !== 'info' ? `｜${freeBless.summary}` : ''}`;
        }
        if (freeBless && freeBless.level !== 'info') return freeBless.summary;
        const success = text.match(/本轮已点击\s*(\d+)\s*封领取；收到服务器奖励记录共\s*(\d+)\s*个龙珠/);
        if (success) {
            const reward = text.match(/服务器奖励记录（[^）]*）：([^；]+)/);
            return `龙珠 +${success[2]}｜邮件 ${success[1]} 封${reward ? `｜${reward[1]}` : ''}`;
        }
        const unconfirmed = text.match(/本轮发现\s*(\d+)\s*封；.*?未收到服务器龙珠奖励记录/);
        if (unconfirmed) {
            const clicked = text.match(/已点击\s*(\d+)\s*封/);
            return `未确认到账｜发现 ${unconfirmed[1]} 封${clicked ? `，点击 ${clicked[1]} 封` : ''}`;
        }
        const gift = text.match(/正在(?:兑换|领取)兑换码“([^”]+)”（本轮第\s*([^；）]+)/);
        if (gift) return `兑换码｜${gift[1]}｜${gift[2]}`;
        if (/检测到官网账号仍处于登录状态/.test(text)) return '退出账号｜官网仍登录，继续确认';

        let compact = text
            .replace(/；\[mail-reward-probe\][\s\S]*?(?=；\[mail-probe\]|；\[日常奖励|；准备退出|$)/g, '')
            .replace(/；\[mail-probe\][\s\S]*?(?=；\[日常奖励|；准备退出|$)/g, '')
            .replace(/；\[日常奖励[^\]]*\][\s\S]*?(?=；准备退出|$)/g, '')
            .replace(/（(?:mail|game|PopUpWindow)[^）]+）/gi, '')
            .replace(/；准备退出$/, '');
        if (level === 'error') compact = compact.replace(/^本轮暂未领到：/, '');
        return compact.length > 116 ? `${compact.slice(0, 113)}…` : compact;
    }

    function normalizeLogEntry(entry) {
        const message = String(entry?.message || '');
        // 始终用当前规则重分并重写历史摘要，避免旧等级或“已恢复”残留影响展示。
        const level = classifyLogMessage(message, entry?.phase);
        return {
            at: Number(entry?.at || 0),
            cycleId: String(entry?.cycleId || ''),
            phase: String(entry?.phase || ''),
            message,
            level,
            summary: compactLogSummary(message, level)
        };
    }

