    function claimStatusMessage(message) {
        const text = String(message || '').trim();
        const freeBless = freeBlessReference(text);
        const freeBlessText = freeBless && freeBless.level !== 'info' ? `免费祈福参考：${freeBless.detail}` : '';
        const strictFeature = text.match(/\[本轮功能结果\][\s\S]*?\[本轮总判定\]\s*(成功|异常)（\d+\/\d+ 项成功）/);
        if (strictFeature) return strictFeature[0];
        const headline = text.match(/JSON 专用自动化完成：[\s\S]*?服务器确认成功\s*\d+、已领取\s*\d+、失败\s*\d+、超时\/未确认\s*\d+/);
        if (!headline) return freeBlessText;
        let result = headline[0].trim();
        const detailStart = text.indexOf('；JSON 逐封结果：', headline.index + headline[0].length);
        if (detailStart < 0) return [result, freeBlessText].filter(Boolean).join('\n');
        const stopMarkers = ['；兑换码', '；刷新状态', '；[日常奖励', '；到账', '；钱包/数值变化', '；官阶', '；未调用现场邮箱', '；准备退出'];
        let detailEnd = text.length;
        for (const marker of stopMarkers) {
            const markerIndex = text.indexOf(marker, detailStart + 1);
            if (markerIndex >= 0 && markerIndex < detailEnd) detailEnd = markerIndex;
        }
        result += text.slice(detailStart, detailEnd);
        return [result.trim(), freeBlessText].filter(Boolean).join('\n');
    }

    function isClaimStatusLog(entry) {
