    function inspectDailyRewardReadiness(bridge) {
        const { selection } = dailyRewardBridgeSelection();
        const active = enabledDailyRewardItems(selection).some((item) => !['mailClaim', 'giftCodes', 'blackMagicOrb'].includes(item.key));
        if (!active) {
            return { ready: true, reason: 'daily-reward-not-needed', missing: [] };
        }
        if (!bridge || typeof bridge.isDailyRewardReady !== 'function') {
            return { ready: false, reason: 'daily-reward-not-ready', missing: ['daily-bridge'] };
        }
        try {
            const result = bridge.isDailyRewardReady(selection);
            return result && result.ready === true
                ? { ready: true, reason: 'ready', missing: [] }
                : {
                    ready: false,
                    reason: result?.reason || 'daily-reward-not-ready',
                    missing: Array.isArray(result?.missing) ? result.missing : []
                };
        } catch (error) {
            return { ready: false, reason: 'daily-reward-readiness-error', missing: [String(error && error.message || error)] };
        }
    }

    

    

