        const dailyPromise = (async () => {
            let text = '';
            try { text = await runDailyRewardsOncePerDay(bridge); } catch (_) {}
            return text;
        })();
        let jsonResult = await mailPromise;
        if (jsonResult?.readinessFailed) {
