        const giftCodePromise = readDailyRewardItems().giftCodes === true
            ? redeemGiftCodesEachCycle(bridge, jsonResult)
            : Promise.resolve('；[日常奖励·兑换码] 已熄灭，本轮未提交（队列保留）');
        const [dailyText, giftCodeText] = await Promise.all([dailyPromise, giftCodePromise]);
        jsonResult = await finalizeJsonWhitelistedArchive(jsonResult);
        const mailDailyText = mailClaimEnabled
