                            : `；[日常奖励·当前邮件并行] 结果未确认 ${Number(jsonResult?.timedOut || 0) + Number(jsonResult?.unconfirmed || 0)}/${Number(jsonResult.eligibleCount)}`)))
                : '；[日常奖励·当前邮件并行] 无可处理附件')
            : '；[日常奖励·当前邮件并行] 已关闭';
        return { mailClaimEnabled, jsonResult, dailyText: mailDailyText + dailyText, giftCodeText, readinessFailed: false };
    }

    

	

    

    

    function findArchiveApi() {
        const queue = [pageWindow];
        const visited = new Set();
        let best = null;
        let bestScore = -1;
        while (queue.length) {
            const target = queue.shift();
            if (!target || visited.has(target)) continue;
            visited.add(target);
            try {
                const api = target.__H5_MAIL_CLAIM_ARCHIVE__;
                if (api) {
                    let snapshot = null;
                    try {
                        snapshot = api.snapshot?.() || null;
                    } catch (_) {}
                    const eligibleCount = jsonArchiveEligibleRecords(snapshot).length;
                    const score =
                        (snapshot?.hasRuntime ? 10 : 0) +
                        (snapshot?.hasMailManager ? 20 : 0) +
                        (String(snapshot?.accountId || '').trim() ? 40 : 0) +
                        (snapshot?.durableStoreLoaded === true ? 80 : 0) +
                        (eligibleCount > 0 ? 160 : 0);
                    if (!best || score > bestScore) {
                        best = api;
                        bestScore = score;
                    }
                }
                for (let index = 0; index < target.frames.length; index += 1) queue.push(target.frames[index]);
            } catch (_) {}
        }
        return best;
    }

    function jsonArchiveEligibleRecords(snapshot) {
        const targetAccountId = String(snapshot?.accountId || '').trim();
        if (!targetAccountId || !Array.isArray(snapshot?.records)) return [];
        return snapshot.records.filter((record) =>
            record?.jsonAutoClaim === true &&
            ['single-gift', 'dbs-item'].includes(record?.claimRoute) &&
            String(record?.accountId || '') === targetAccountId
        );
    }

    function evaluateJsonArchiveReadiness(snapshot, restored = {}) {
        if (!snapshot?.hasRuntime) {
            return { ready: false, reason: 'runtime-not-ready', eligible: [] };
