    function calculationAlive(job){
        var t=g.__SGSOL_MOBILE_BATTLE__;
        if(hiddenForSession||page!=='calculation'||calculation!==job||g.Laya.stage!==job.stage||g.__SGSOL_ACCOUNT_ID_RESOLVER__.snapshot().sessionEpoch!==job.epoch||t.nodes().indexOf(job.source.window)<0)return false;
        if(job.kind==='peixiu'){var s=job.source.window.mapState;return job.source.signature===JSON.stringify([s.mapId,s.currentPos,s.drawnCells]);}
        return job.signature===JSON.stringify(job.source.window.allCardUIs.map(function(ui){return ui.Card&&ui.Card.CardId;}));
    }
    function beginCalculation(kind){
        var source=g.__SGSOL_MOBILE_BATTLE__[kind]();
        var job={kind:kind,source:source,stage:g.Laya.stage,epoch:g.__SGSOL_ACCOUNT_ID_RESOLVER__.snapshot().sessionEpoch,started:Date.now(),signature:kind==='yanJiao'?JSON.stringify(source.window.allCardUIs.map(function(ui){return ui.Card&&ui.Card.CardId;})):''};
        calculation=job;page='calculation';toolResult='计算中…';render();
        function step(){
            if(!calculationAlive(job)){if(calculation===job){calculation=null;toolResult='窗口或局面变化，请重新计算';render();}return;}
            var result=source.search.step(250);
            if(result.status==='working'){
                if(Date.now()-job.started>3000){toolResult='计算达到时间上限，未给出完整结果';job.done=true;render();return;}
                g.setTimeout(step,0);return;
            }
            job.done=true;
            if(kind==='yanJiao')toolResult=result.solutions.map(function(v,i){return (i+1)+'. '+v.left.join('+')+' = '+v.right.join('+')+' = '+v.sum+'；剩余 '+(v.remaining.join(',')||'无');}).join('\n')||'无等点数分法';
            else toolResult=result.found?'路线：'+result.actions.map(function(a){return a.suit+a.from+'→'+a.to;}).join(' / ')+'\n共 '+result.steps+' 步；'+JSON.stringify(result.counts):result.reason;
            render();
        }
        g.setTimeout(step,0);
    }
